/// One finite contact between a selected algebraic semicircle and a
/// certified axis-aligned retained chord.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct BezierAlgebraicCuspSemicircleChordContact2 {
    /// `-1` and `+1` select the two transverse support contacts; zero is the
    /// unique tangent contact.  Branch order follows the chord traversal.
    branch: i8,
    /// Exact singleton interval for a line parameter retained directly over
    /// the selected circle-center field. Legacy analytic fast paths encode
    /// their contact through `branch` and leave this absent.
    selected_fiber_parameter: Option<BezierAlgebraicSelectedFiberParameter2>,
    pub(crate) cusp_location: BezierAlgebraicCuspSemicircleContactLocation2,
    pub(crate) chord_location: BezierAlgebraicCuspSemicircleContactLocation2,
    pub(crate) tangent_cross_sign: RealSign,
}

#[derive(Clone, Debug)]
pub(crate) enum BezierAlgebraicCuspSemicircleChordIntersections2 {
    NoContacts,
    Contacts {
        contacts: Vec<BezierAlgebraicCuspSemicircleChordContact2>,
        parameter_map: BezierAlgebraicCuspSemicircleChordParameterMap2,
    },
}

/// One fully retained finite contact produced by the authoritative selected
/// semicircle/chord kernel.  Fast paths may use different local elimination
/// systems, but callers receive the same exact carrier parameters and point
/// evidence.
#[derive(Clone, Debug)]
pub(crate) struct BezierAlgebraicCuspSemicircleRetainedChordContact2 {
    pub(crate) cusp_parameter: BezierAlgebraicCuspSemicircleParameter2,
    pub(crate) chord_parameter: BezierAlgebraicChordParameter2,
    pub(crate) point: RationalBezierIntersectionPointEvidence2,
    pub(crate) tangent_cross_sign: RealSign,
}

#[derive(Clone, Debug)]
pub(crate) enum BezierAlgebraicCuspSemicircleRetainedChordIntersections2 {
    NoContacts,
    Contacts(Vec<BezierAlgebraicCuspSemicircleRetainedChordContact2>),
}

/// Exact affine point retained by a selected algebraic-circle/axis-chord
/// contact.  The one-word carrier shares the same map/contact allocation as
/// the corresponding mapped semicircle parameter.
#[derive(Clone, Debug)]
pub struct BezierAlgebraicCuspChordPoint2 {
    data: Arc<BezierAlgebraicCuspSemicircleMappedParameterData2>,
}

/// One-word exact point derived from a correlated selected-circle contact
/// without flattening its selected fields.
///
/// Chord contacts reuse their original radical system. Other mapped contacts
/// retain their exact source point and selected-circle parameter proof, then
/// refine those two existing fields independently for nonstructural queries.
/// No primitive element or approximate construction coordinate is introduced.
#[derive(Clone, Debug)]
pub struct BezierAlgebraicCuspChordDerivedPoint2 {
    data: Arc<BezierAlgebraicCuspChordDerivedPointData2>,
}

#[derive(Debug)]
struct BezierAlgebraicCuspChordDerivedPointData2 {
    source: BezierAlgebraicCuspDerivedPointSource2,
    radial_scale: Real,
    /// Coefficient of the counterclockwise perpendicular source radius.
    /// Existing concentric offsets keep this zero; retained cusp chamfers use
    /// it to rotate a mapped endpoint without constructing a compositum.
    perpendicular_scale: Real,
    translation_x: Real,
    translation_y: Real,
}

#[derive(Clone, Debug)]
enum BezierAlgebraicCuspDerivedPointSource2 {
    Chord(BezierAlgebraicCuspChordPoint2),
    Mapped {
        parameter: Arc<BezierAlgebraicCuspSemicircleMappedParameterData2>,
        /// A one-field point image when the mapped carrier can publish one.
        /// General analytic parallels retain `None` and evaluate their exact
        /// point bounds lazily from the native parameter and unit normal.
        point: Option<RationalBezierIntersectionPointEvidence2>,
    },
}

impl PartialEq for BezierAlgebraicCuspDerivedPointSource2 {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Self::Chord(first), Self::Chord(second)) => first == second,
            (
                Self::Mapped {
                    parameter: first_parameter,
                    point: first_point,
                },
                Self::Mapped {
                    parameter: second_parameter,
                    point: second_point,
                },
            ) => Arc::ptr_eq(first_parameter, second_parameter) && first_point == second_point,
            (Self::Chord(_), Self::Mapped { .. }) | (Self::Mapped { .. }, Self::Chord(_)) => false,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[allow(dead_code)]
pub(crate) enum BezierAlgebraicCuspSemicirclePairEndpoint2 {
    FirstStart,
    FirstEnd,
    SecondStart,
    SecondEnd,
}

/// One-word exact positive-length overlap between two selected algebraic
/// semicircles on the same supporting circle.
#[derive(Clone, Debug)]
#[allow(dead_code)]
pub(crate) struct BezierAlgebraicCuspSemicirclePairOverlap2 {
    data: Arc<BezierAlgebraicCuspSemicirclePairOverlapData2>,
}

/// Exact local parameter on one retained algebraic-cusp semicircle.
///
/// Interior values retain the pair/contact predicate that orders the value
/// against any represented rational parameter. This deliberately avoids a
/// primitive element for the independent selected roots. Exact values remain
/// inline, while mapped values share their larger proof through one pointer.
#[derive(Clone, Debug)]
#[allow(dead_code)]
pub(crate) enum BezierAlgebraicCuspSemicircleParameter2 {
    Exact(Real),
    Mapped(Arc<BezierAlgebraicCuspSemicircleMappedParameterData2>),
}

#[derive(Debug)]
pub(crate) enum BezierSelectedChordNormalAnchor2 {
    Represented((Real, Real)),
    RetainedCircleChord {
        map: BezierAlgebraicCuspSemicircleChordParameterMap2,
        contact: BezierAlgebraicCuspSemicircleChordContact2,
        target_tangent_reversed: bool,
    },
}

#[derive(Debug)]
#[allow(dead_code)]
pub(crate) enum BezierAlgebraicCuspSemicircleMappedParameterData2 {
    Rational {
        map: BezierAlgebraicCuspSemicircleRationalParameterMap2,
        contact: BezierAlgebraicCuspSemicircleRationalMapContact2,
    },
    SelectedFiberRational {
        map: BezierAlgebraicCuspSemicircleSelectedFiberRationalParameterMap2,
        other_parameter: BezierAlgebraicSelectedFiberParameter2,
        location: BezierAlgebraicCuspSemicircleContactLocation2,
        tangent_cross_sign: RealSign,
    },
    SelectedFiberParallel {
        map: BezierAlgebraicCuspSemicircleSelectedFiberParallelParameterMap2,
        other_parameter: BezierAlgebraicSelectedFiberParameter2,
        location: BezierAlgebraicCuspSemicircleContactLocation2,
        tangent_cross_sign: RealSign,
    },
    Parallel {
        map: BezierAlgebraicCuspSemicircleParallelParameterMap2,
        contact: BezierAlgebraicCuspSemicircleParallelContact2,
    },
    /// A fillet contact retained directly in the two selected source-tangent
    /// fields that define its angular position.
    ///
    /// The circle start radius is a signed left normal of its selected frame;
    /// the contact radius is a signed left normal of `parallel`.  Their sign
    /// product plus the two unnormalized source tangents orders the contact
    /// against every represented circle parameter without a square root,
    /// resultant, or primitive element.
    SelectedParallelContact {
        semicircle: BezierAlgebraicCuspSemicircle2,
        parallel: BezierParallel2,
        parameter: BezierParameter2,
        radial_product_sign: RealSign,
        tangent_cross_sign: RealSign,
        tangent_dot_sign: RealSign,
        policy: CurveContext,
    },
    /// One round-join endpoint whose contact radial is the signed left normal
    /// of a retained selected-circle traversal tangent.
    ///
    /// The companion endpoint already owns the two-normal circle/parallel
    /// contact map. Reusing that map to order this angular parameter avoids a
    /// four-field circle-circle or oblique-chord reconstruction.
    SelectedCircularTangentContact {
        semicircle: BezierAlgebraicCuspSemicircle2,
        companion: BezierAlgebraicCuspSemicircleFragment2,
        companion_at_start: bool,
        parallel: BezierParallel2,
        parameter: BezierParameter2,
        source_direction: RealSign,
        radial_product_sign: RealSign,
        point: RationalBezierIntersectionPointEvidence2,
        policy: CurveContext,
    },
    /// One fillet endpoint retained directly from the independent selected
    /// circle-pair contact that solved the fillet center.
    ///
    /// `anchor_first` records which pair carrier supplies this circle's start
    /// radial. The pair map then signs every angular comparison from its
    /// shared dot/discriminant representation, without constructing a
    /// primitive element for the two selected fields.
    SelectedPairContact {
        semicircle: BezierAlgebraicCuspSemicircle2,
        map: BezierAlgebraicCuspSemicirclePairParameterMap2,
        contact: BezierAlgebraicCuspSemicirclePairContact2,
        anchor_first: bool,
        radial_product_sign: RealSign,
        point: RationalBezierIntersectionPointEvidence2,
        policy: CurveContext,
    },
    /// One exact round-join endpoint whose radial direction is the signed
    /// left normal of a retained algebraic chord.
    ///
    /// `anchor_tangent` and `chord` are the covariant local angular authority
    /// from the authored join. The anchor is either a represented vector or
    /// the exact retained circle/chord tangent map that produced the center.
    /// `radial_product_sign` also covers a contact on the complementary half
    /// without changing that authority. A similarity preserves their angular
    /// relation; represented anchors transform in place, while retained maps
    /// use the generic exact transport. This avoids adjoining the chord's
    /// endpoint fields and normalization radical to the selected-circle field.
    SelectedChordNormalContact {
        semicircle: BezierAlgebraicCuspSemicircle2,
        anchor_tangent: BezierSelectedChordNormalAnchor2,
        chord: BezierAlgebraicChord2,
        radial_product_sign: RealSign,
        point: RationalBezierIntersectionPointEvidence2,
        policy: CurveContext,
    },
    /// One exact round-join endpoint whose radial is a retained chord normal
    /// and whose circle chart starts on an analytic-parallel normal.
    ///
    /// The selected center parameter and two independent chord endpoint fields
    /// remain separate. Angular predicates sign only the required
    /// chord/parallel tangent linear combination at the decision boundary.
    SelectedChordParallelNormalContact {
        semicircle: BezierAlgebraicCuspSemicircle2,
        parallel: BezierParallel2,
        parallel_parameter: BezierParameter2,
        chord: BezierAlgebraicChord2,
        radial_product_sign: RealSign,
        point: RationalBezierIntersectionPointEvidence2,
        policy: CurveContext,
    },
    Pair {
        map: BezierAlgebraicCuspSemicirclePairParameterMap2,
        contact: BezierAlgebraicCuspSemicirclePairContact2,
        first: bool,
    },
    Chord {
        map: BezierAlgebraicCuspSemicircleChordParameterMap2,
        contact: BezierAlgebraicCuspSemicircleChordContact2,
    },
    PairOverlap {
        overlap: BezierAlgebraicCuspSemicirclePairOverlap2,
        endpoint: BezierAlgebraicCuspSemicirclePairEndpoint2,
        first: bool,
    },
    PairOverlapMap {
        overlap: BezierAlgebraicCuspSemicirclePairOverlap2,
        source: BezierAlgebraicCuspSemicircleParameter2,
        source_first: bool,
    },
    /// A mapped local parameter transported by one certified similarity.
    ///
    /// The selected-circle chart is similarity covariant: its scalar
    /// parameter is unchanged even under reflection because the transformed
    /// frame, signed radius, and traversal turn are reflected together.  The
    /// source parameter therefore remains the exact ordering authority while
    /// `point` retains the transformed Cartesian evidence without constructing
    /// a compositum for either selected field.
    SimilarityTransport {
        semicircle: BezierAlgebraicCuspSemicircle2,
        source: BezierAlgebraicCuspSemicircleParameter2,
        point: RationalBezierIntersectionPointEvidence2,
        policy: CurveContext,
    },
    /// Exact angular transport on one selected supporting circle.
    ///
    /// `half_angle` is `tan(theta / 2)` in the semicircle's increasing local
    /// parameter direction. The target parameter is the corresponding
    /// Mobius transform of `source`; `point` retains the same construction as
    /// a center-relative rotation of the source point.
    Chamfer {
        semicircle: BezierAlgebraicCuspSemicircle2,
        source: BezierAlgebraicCuspSemicircleParameter2,
        half_angle: Real,
        point: RationalBezierIntersectionPointEvidence2,
        policy: CurveContext,
    },
}

enum BezierAlgebraicCuspSemicircleMappedTangentSource2<'a> {
    Rational {
        curve: &'a RationalBezier2,
        parameter: &'a BezierParameter2,
        policy: CurveContext,
    },
    Parallel {
        parallel: &'a BezierParallel2,
        parameter: &'a BezierParameter2,
        policy: CurveContext,
    },
}

impl BezierAlgebraicCuspSemicircleMappedTangentSource2<'_> {
    fn policy(&self) -> CurveContext {
        match self {
            Self::Rational { policy, .. } | Self::Parallel { policy, .. } => *policy,
        }
    }

    fn parameter(&self) -> &BezierParameter2 {
        match self {
            Self::Rational { parameter, .. } | Self::Parallel { parameter, .. } => parameter,
        }
    }

    fn tangent_power_basis(&self) -> CurveResult<[Vec<Real>; 2]> {
        match self {
            Self::Rational { curve, .. } => Ok(rational_parametric_tangent_numerator(
                curve.homogeneous_power_basis()?,
            )),
            Self::Parallel { parallel, .. } => {
                let differential = parallel.differential()?;
                Ok([
                    differential.tangent_x.clone(),
                    differential.tangent_y.clone(),
                ])
            }
        }
    }
}

/// Encloses one exact analytic-parallel point without adjoining its normalized
/// tangent field to the retained source parameter.
fn analytic_parallel_point_bounds_refined(
    parallel: &BezierParallel2,
    parameter: &BezierParameter2,
    tangent_distance: &Real,
    translation_x: &Real,
    translation_y: &Real,
    refinement_steps: usize,
    policy: &CurveContext,
) -> Classification<Aabb2> {
    let parameter = parameter
        .clone()
        .refined_isolating_interval(refinement_steps, policy);
    let parameter = BezierAlgebraicChordRealInterval2::from_parameter(&parameter);
    analytic_parallel_point_bounds_over_interval(
        parallel,
        &parameter,
        tangent_distance,
        translation_x,
        translation_y,
    )
}

fn analytic_parallel_point_bounds_over_interval(
    parallel: &BezierParallel2,
    parameter: &BezierAlgebraicChordRealInterval2,
    tangent_distance: &Real,
    translation_x: &Real,
    translation_y: &Real,
) -> Classification<Aabb2> {
    let strict = &CurveContext::STRICT;
    let evaluate = |polynomial: &[Real]| {
        BezierAlgebraicChordRealInterval2::evaluate_power_basis(polynomial, parameter, strict)
    };
    let differential = match parallel.differential() {
        Ok(differential) => differential,
        Err(_) => return Classification::Uncertain(UncertaintyReason::Unsupported),
    };
    let (Some(tangent_x), Some(tangent_y)) = (
        evaluate(&differential.tangent_x),
        evaluate(&differential.tangent_y),
    ) else {
        return Classification::Uncertain(UncertaintyReason::Ordering);
    };
    let Some(speed) = tangent_x
        .square(strict)
        .and_then(|x| tangent_y.square(strict).map(|y| x.add(&y)))
        .and_then(|speed_squared| speed_squared.nonnegative_square_root(strict))
    else {
        return Classification::Uncertain(UncertaintyReason::Ordering);
    };
    let Some(normal_x) = (BezierAlgebraicChordRealInterval2 {
        lower: -tangent_y.upper.clone(),
        upper: -tangent_y.lower.clone(),
    })
    .divide(&speed, strict) else {
        return Classification::Uncertain(UncertaintyReason::Ordering);
    };
    let Some(normal_y) = tangent_x.divide(&speed, strict) else {
        return Classification::Uncertain(UncertaintyReason::Ordering);
    };
    let source = match parallel.source_power_basis() {
        Ok(source) => source,
        Err(_) => return Classification::Uncertain(UncertaintyReason::Unsupported),
    };
    let (Some(mut point_x), Some(mut point_y)) =
        (evaluate(source.x_numerator), evaluate(source.y_numerator))
    else {
        return Classification::Uncertain(UncertaintyReason::Ordering);
    };
    if let Some(weight) = source.weight {
        let Some(weight) = evaluate(weight) else {
            return Classification::Uncertain(UncertaintyReason::Ordering);
        };
        let (Some(x), Some(y)) = (
            point_x.divide(&weight, strict),
            point_y.divide(&weight, strict),
        ) else {
            return Classification::Uncertain(UncertaintyReason::Ordering);
        };
        point_x = x;
        point_y = y;
    }
    let distance = BezierAlgebraicChordRealInterval2 {
        lower: parallel.distance().clone(),
        upper: parallel.distance().clone(),
    };
    let tangent_distance = BezierAlgebraicChordRealInterval2 {
        lower: tangent_distance.clone(),
        upper: tangent_distance.clone(),
    };
    let (
        Some(normal_offset_x),
        Some(normal_offset_y),
        Some(tangent_offset_x),
        Some(tangent_offset_y),
    ) = (
        normal_x.multiply(&distance, strict),
        normal_y.multiply(&distance, strict),
        tangent_x
            .divide(&speed, strict)
            .and_then(|unit| unit.multiply(&tangent_distance, strict)),
        tangent_y
            .divide(&speed, strict)
            .and_then(|unit| unit.multiply(&tangent_distance, strict)),
    )
    else {
        return Classification::Uncertain(UncertaintyReason::Ordering);
    };
    let point_x = point_x.add(&normal_offset_x).add(&tangent_offset_x).add(
        &BezierAlgebraicChordRealInterval2 {
            lower: translation_x.clone(),
            upper: translation_x.clone(),
        },
    );
    let point_y = point_y.add(&normal_offset_y).add(&tangent_offset_y).add(
        &BezierAlgebraicChordRealInterval2 {
            lower: translation_y.clone(),
            upper: translation_y.clone(),
        },
    );
    Classification::Decided(Aabb2::new_unchecked(
        Point2::new(point_x.lower, point_y.lower),
        Point2::new(point_x.upper, point_y.upper),
    ))
}

impl BezierAlgebraicCuspSemicircleMappedParameterData2 {
    /// Returns the selected semicircle on which this retained parameter was
    /// authored. This identity prevents a genuinely mapped point from being
    /// replayed after its fragment was transformed without transforming the
    /// correlation itself.
    fn semicircle_carrier(&self) -> &BezierAlgebraicCuspSemicircle2 {
        match self {
            Self::Rational { map, .. } => &map.data.semicircle,
            Self::SelectedFiberRational { map, .. } => &map.data.semicircle,
            Self::SelectedFiberParallel { map, .. } => &map.data.semicircle,
            Self::Parallel { map, .. } => &map.data.semicircle,
            Self::SelectedParallelContact { semicircle, .. } => semicircle,
            Self::SelectedCircularTangentContact { semicircle, .. } => semicircle,
            Self::SelectedPairContact { semicircle, .. } => semicircle,
            Self::SelectedChordNormalContact { semicircle, .. }
            | Self::SelectedChordParallelNormalContact { semicircle, .. } => semicircle,
            Self::Pair { map, first, .. } => {
                if *first {
                    &map.data.first_semicircle
                } else {
                    &map.data.second_semicircle
                }
            }
            Self::Chord { map, .. } => &map.data.semicircle,
            Self::PairOverlap { overlap, first, .. } => overlap.semicircle(*first),
            Self::PairOverlapMap {
                overlap,
                source_first,
                ..
            } => overlap.semicircle(!*source_first),
            Self::SimilarityTransport { semicircle, .. } => semicircle,
            Self::Chamfer { semicircle, .. } => semicircle,
        }
    }

    /// Returns point evidence stored directly beside this mapped parameter.
    fn retained_point_evidence(&self) -> Option<&RationalBezierIntersectionPointEvidence2> {
        match self {
            Self::SelectedCircularTangentContact { point, .. }
            | Self::SelectedPairContact { point, .. }
            | Self::SelectedChordNormalContact { point, .. }
            | Self::SelectedChordParallelNormalContact { point, .. }
            | Self::SimilarityTransport { point, .. }
            | Self::Chamfer { point, .. } => Some(point),
            Self::Rational { .. }
            | Self::SelectedFiberRational { .. }
            | Self::SelectedFiberParallel { .. }
            | Self::Parallel { .. }
            | Self::SelectedParallelContact { .. }
            | Self::Pair { .. }
            | Self::Chord { .. }
            | Self::PairOverlap { .. }
            | Self::PairOverlapMap { .. } => None,
        }
    }

    fn selected_parallel_contact_order_to_real(
        &self,
        represented: &Real,
    ) -> CurveResult<Classification<std::cmp::Ordering>> {
        let Self::SelectedParallelContact {
            semicircle,
            parallel,
            parameter,
            radial_product_sign,
            tangent_cross_sign,
            tangent_dot_sign,
            policy,
        } = self
        else {
            return Err(CurveError::Topology(
                "a non-selected contact requested selected-frame angular ordering".into(),
            ));
        };
        match in_closed_unit_interval(represented, policy) {
            Some(true) => {}
            Some(false) => return Err(CurveError::InvalidBezierParameter),
            None => return Ok(Classification::Uncertain(UncertaintyReason::Ordering)),
        }
        let one_minus = Real::one() - represented;
        let radial = Real::one() - Real::from(2_i8) * represented;
        let tangential = Real::from(2_i8) * represented * one_minus;
        let turn = Real::from(if semicircle.is_clockwise() {
            -1_i8
        } else {
            1_i8
        });
        let signed_term =
            |coefficient: &Real, term_sign: RealSign| -> CurveResult<Classification<RealSign>> {
                Ok(match real_sign(coefficient, policy) {
                    Some(coefficient_sign) => {
                        Classification::Decided(product_sign(coefficient_sign, term_sign))
                    }
                    None => Classification::Uncertain(UncertaintyReason::RealSign),
                })
            };
        let certified = if tangential.zero_status() == ZeroStatus::Zero
            || *tangent_dot_sign == RealSign::Zero
        {
            Some(signed_term(
                &(-(radial.clone() * &turn)),
                *tangent_cross_sign,
            )?)
        } else if radial.zero_status() == ZeroStatus::Zero || *tangent_cross_sign == RealSign::Zero
        {
            Some(signed_term(&tangential, *tangent_dot_sign)?)
        } else {
            None
        };
        let raw_sign = if let Some(certified) = certified {
            match certified {
                Classification::Decided(sign) => sign,
                Classification::Uncertain(reason) => {
                    return Ok(Classification::Uncertain(reason));
                }
            }
        } else {
            let anchor = semicircle.source_parallel().ok_or_else(|| {
                CurveError::Topology(
                    "a selected parallel contact lost its source-normal frame".into(),
                )
            })?;
            let anchor_parameter = semicircle.selected_frame_parameter().ok_or_else(|| {
                CurveError::Topology(
                    "a selected parallel contact had no single center parameter".into(),
                )
            })?;
            let anchor_tangent = anchor.differential()?;
            let contact_tangent = parallel.differential()?;
            let tangent_cross = bivariate_subtract(
                &bivariate_outer_product(&anchor_tangent.tangent_x, &contact_tangent.tangent_y),
                &bivariate_outer_product(&anchor_tangent.tangent_y, &contact_tangent.tangent_x),
            );
            let tangent_dot = bivariate_add(
                &bivariate_outer_product(&anchor_tangent.tangent_x, &contact_tangent.tangent_x),
                &bivariate_outer_product(&anchor_tangent.tangent_y, &contact_tangent.tangent_y),
            );
            let predicate = bivariate_subtract(
                &bivariate_scale(tangent_dot, &tangential),
                &bivariate_scale(tangent_cross, &(radial * turn)),
            );
            match signed_bivariate_at_parameter_pair(
                &predicate,
                &anchor_parameter,
                parameter,
                policy,
            )? {
                Classification::Decided(sign) => sign,
                Classification::Uncertain(reason) => {
                    return Ok(Classification::Uncertain(reason));
                }
            }
        };
        let sign = if *radial_product_sign == RealSign::Negative {
            product_sign(raw_sign, RealSign::Negative)
        } else {
            raw_sign
        };
        Ok(Classification::Decided(match sign {
            // Positive is sin(represented_angle - contact_angle).
            RealSign::Positive => std::cmp::Ordering::Less,
            RealSign::Negative => std::cmp::Ordering::Greater,
            RealSign::Zero => std::cmp::Ordering::Equal,
        }))
    }

    fn selected_parallel_contact_parameter_bracket(
        &self,
        refinement_steps: usize,
    ) -> CurveResult<Classification<BezierAlgebraicCuspSemicircleParameterBracket2>> {
        let Self::SelectedParallelContact { policy, .. } = self else {
            return Err(CurveError::Topology(
                "a non-selected contact requested selected-frame angular refinement".into(),
            ));
        };
        algebraic_cusp_semicircle_contact_parameter_bracket(
            BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            refinement_steps,
            policy,
            |parameter| self.selected_parallel_contact_order_to_real(parameter),
        )
    }

    fn selected_circular_tangent_contact_order_to_real(
        &self,
        represented: &Real,
    ) -> CurveResult<Classification<std::cmp::Ordering>> {
        let Self::SelectedCircularTangentContact {
            semicircle,
            companion,
            companion_at_start,
            parallel,
            parameter,
            source_direction,
            radial_product_sign,
            policy,
            ..
        } = self
        else {
            return Err(CurveError::Topology(
                "a non-circular contact requested selected-circle angular ordering".into(),
            ));
        };
        match in_closed_unit_interval(represented, policy) {
            Some(true) => {}
            Some(false) => return Err(CurveError::InvalidBezierParameter),
            None => return Ok(Classification::Uncertain(UncertaintyReason::Ordering)),
        }
        let one_minus = Real::one() - represented;
        let radial = Real::one() - Real::from(2_i8) * represented;
        let tangential = Real::from(2_i8) * represented * one_minus;
        let turn = Real::from(if semicircle.is_clockwise() {
            -1_i8
        } else {
            1_i8
        });
        // The companion primitive evaluates T_companion x T_anchor. The
        // selected-circle angular predicate is
        //   tangential*(T_anchor dot T_companion)
        //     - radial*turn*(T_anchor x T_companion),
        // hence the positive cross coefficient below after swapping the
        // cross operands.
        let cross_scale = radial * turn;
        let raw_sign = match companion
            .endpoint_tangent_cross_dot_linear_combination_retained_parallel(
                *companion_at_start,
                parallel,
                parameter,
                *source_direction,
                &cross_scale,
                &tangential,
                policy,
            )? {
            Classification::Decided(Some(sign)) => sign,
            Classification::Decided(None) => {
                return Ok(Classification::Uncertain(UncertaintyReason::Unsupported));
            }
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        };
        let sign = product_sign(raw_sign, *radial_product_sign);
        Ok(Classification::Decided(match sign {
            RealSign::Positive => std::cmp::Ordering::Less,
            RealSign::Negative => std::cmp::Ordering::Greater,
            RealSign::Zero => std::cmp::Ordering::Equal,
        }))
    }

    fn selected_circular_tangent_contact_parameter_bracket(
        &self,
        refinement_steps: usize,
    ) -> CurveResult<Classification<BezierAlgebraicCuspSemicircleParameterBracket2>> {
        let Self::SelectedCircularTangentContact { policy, .. } = self else {
            return Err(CurveError::Topology(
                "a non-circular contact requested selected-circle angular refinement".into(),
            ));
        };
        algebraic_cusp_semicircle_contact_parameter_bracket(
            BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            refinement_steps,
            policy,
            |parameter| self.selected_circular_tangent_contact_order_to_real(parameter),
        )
    }

    fn selected_pair_contact_order_to_real(
        &self,
        represented: &Real,
    ) -> CurveResult<Classification<std::cmp::Ordering>> {
        let Self::SelectedPairContact {
            semicircle,
            map,
            contact,
            anchor_first,
            radial_product_sign,
            policy,
            ..
        } = self
        else {
            return Err(CurveError::Topology(
                "a non-pair contact requested selected-circle angular ordering".into(),
            ));
        };
        match in_closed_unit_interval(represented, policy) {
            Some(true) => {}
            Some(false) => return Err(CurveError::InvalidBezierParameter),
            None => return Ok(Classification::Uncertain(UncertaintyReason::Ordering)),
        }
        let one_minus = Real::one() - represented;
        let radial = Real::one() - Real::from(2_i8) * represented;
        let tangential = Real::from(2_i8) * represented * one_minus;
        let turn = semicircle.turn_sign();
        let mut cross_scale = -(radial * turn);
        if !anchor_first {
            cross_scale = -cross_scale;
        }
        let raw_sign = match map.tangent_cross_dot_linear_combination_sign(
            contact,
            &cross_scale,
            &tangential,
            policy,
        )? {
            Classification::Decided(sign) => sign,
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        };
        let sign = product_sign(raw_sign, *radial_product_sign);
        Ok(Classification::Decided(match sign {
            RealSign::Positive => std::cmp::Ordering::Less,
            RealSign::Negative => std::cmp::Ordering::Greater,
            RealSign::Zero => std::cmp::Ordering::Equal,
        }))
    }

    fn selected_pair_contact_parameter_bracket(
        &self,
        refinement_steps: usize,
    ) -> CurveResult<Classification<BezierAlgebraicCuspSemicircleParameterBracket2>> {
        let Self::SelectedPairContact { policy, .. } = self else {
            return Err(CurveError::Topology(
                "a non-pair contact requested selected-circle angular refinement".into(),
            ));
        };
        algebraic_cusp_semicircle_contact_parameter_bracket(
            BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            refinement_steps,
            policy,
            |parameter| self.selected_pair_contact_order_to_real(parameter),
        )
    }

    fn selected_chord_normal_contact_order_to_real(
        &self,
        represented: &Real,
    ) -> CurveResult<Classification<std::cmp::Ordering>> {
        let Self::SelectedChordNormalContact {
            semicircle,
            anchor_tangent,
            chord,
            radial_product_sign,
            policy,
            ..
        } = self
        else {
            return Err(CurveError::Topology(
                "a non-chord contact requested selected-circle angular ordering".into(),
            ));
        };
        match in_closed_unit_interval(represented, policy) {
            Some(true) => {}
            Some(false) => return Err(CurveError::InvalidBezierParameter),
            None => return Ok(Classification::Uncertain(UncertaintyReason::Ordering)),
        }
        let one_minus = Real::one() - represented;
        let radial = Real::one() - Real::from(2_i8) * represented;
        let tangential = Real::from(2_i8) * represented * one_minus;
        let turn = Real::from(if semicircle.is_clockwise() {
            -1_i8
        } else {
            1_i8
        });
        // For represented radial R(u) and contact radial left_normal(D), the
        // sign of sin(angle(u)-angle(contact)) is the same as
        //   tangential * (T_anchor dot D)
        //     - radial * turn * (T_anchor x D).
        // The positive chord speed cancels. The retained radial-product sign
        // covers either equal signed radii or the complementary chart.
        let cross_scale = -(radial * turn);
        let raw_sign = match match anchor_tangent {
            BezierSelectedChordNormalAnchor2::Represented(anchor_tangent) => chord
                .tangent_cross_dot_vector_linear_combination_sign(
                    anchor_tangent,
                    &cross_scale,
                    &tangential,
                    policy,
                )?,
            BezierSelectedChordNormalAnchor2::RetainedCircleChord {
                map,
                contact,
                target_tangent_reversed,
            } => map
                .retained_offset_tangent_cross_dot_linear_combination_sign(
                    contact,
                    &cross_scale,
                    &tangential,
                )?
                .map(|sign| {
                    if *target_tangent_reversed {
                        product_sign(sign, RealSign::Negative)
                    } else {
                        sign
                    }
                }),
        } {
            Classification::Decided(sign) => sign,
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        };
        let sign = product_sign(raw_sign, *radial_product_sign);
        Ok(Classification::Decided(match sign {
            RealSign::Positive => std::cmp::Ordering::Less,
            RealSign::Negative => std::cmp::Ordering::Greater,
            RealSign::Zero => std::cmp::Ordering::Equal,
        }))
    }

    fn selected_chord_normal_contact_parameter_bracket(
        &self,
        refinement_steps: usize,
    ) -> CurveResult<Classification<BezierAlgebraicCuspSemicircleParameterBracket2>> {
        let Self::SelectedChordNormalContact { policy, .. } = self else {
            return Err(CurveError::Topology(
                "a non-chord contact requested selected-circle angular refinement".into(),
            ));
        };
        algebraic_cusp_semicircle_contact_parameter_bracket(
            BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            refinement_steps,
            policy,
            |parameter| self.selected_chord_normal_contact_order_to_real(parameter),
        )
    }

    fn selected_chord_parallel_normal_contact_order_to_real(
        &self,
        represented: &Real,
    ) -> CurveResult<Classification<std::cmp::Ordering>> {
        let Self::SelectedChordParallelNormalContact {
            semicircle,
            parallel,
            parallel_parameter,
            chord,
            radial_product_sign,
            policy,
            ..
        } = self
        else {
            return Err(CurveError::Topology(
                "a non-chord contact requested selected parallel-frame angular ordering".into(),
            ));
        };
        match in_closed_unit_interval(represented, policy) {
            Some(true) => {}
            Some(false) => return Err(CurveError::InvalidBezierParameter),
            None => return Ok(Classification::Uncertain(UncertaintyReason::Ordering)),
        }
        let one_minus = Real::one() - represented;
        let radial = Real::one() - Real::from(2_i8) * represented;
        let tangential = Real::from(2_i8) * represented * one_minus;
        let turn = Real::from(if semicircle.is_clockwise() {
            -1_i8
        } else {
            1_i8
        });
        // The selected chart starts on left_normal(T_parallel), while the
        // contact radial is left_normal(T_chord).  The angular predicate is
        //   tangential * (T_parallel dot T_chord)
        //     - radial * turn * (T_parallel x T_chord).
        // The chord primitive signs the swapped cross product, so its cross
        // coefficient is positive `radial * turn`.
        let raw_sign = match chord.tangent_cross_dot_parallel_linear_combination_sign(
            parallel,
            parallel_parameter,
            &(radial * turn),
            &tangential,
            policy,
        )? {
            Classification::Decided(sign) => sign,
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        };
        let sign = product_sign(raw_sign, *radial_product_sign);
        Ok(Classification::Decided(match sign {
            RealSign::Positive => std::cmp::Ordering::Less,
            RealSign::Negative => std::cmp::Ordering::Greater,
            RealSign::Zero => std::cmp::Ordering::Equal,
        }))
    }

    fn selected_chord_parallel_normal_contact_parameter_bracket(
        &self,
        refinement_steps: usize,
    ) -> CurveResult<Classification<BezierAlgebraicCuspSemicircleParameterBracket2>> {
        let Self::SelectedChordParallelNormalContact { policy, .. } = self else {
            return Err(CurveError::Topology(
                "a non-chord contact requested selected parallel-frame angular refinement".into(),
            ));
        };
        algebraic_cusp_semicircle_contact_parameter_bracket(
            BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            refinement_steps,
            policy,
            |parameter| self.selected_chord_parallel_normal_contact_order_to_real(parameter),
        )
    }

    /// Returns the original mapped carrier below every exact
    /// coincident-circle transport.
    ///
    /// `PairOverlapMap` changes only the selected-circle parameterization; it
    /// does not move the physical point.  Geometry certificates such as a
    /// common cardinal coordinate must therefore be replayed against this
    /// base carrier, even when the destination overlap uses a general
    /// correlated parameter map rather than identity or unit complement.
    fn coincident_base_data(&self) -> &Self {
        match self {
            Self::PairOverlapMap {
                source: BezierAlgebraicCuspSemicircleParameter2::Mapped(source),
                ..
            } => source.coincident_base_data(),
            _ => self,
        }
    }

    /// Recovers the rational carrier at the base of any exact coincident-circle
    /// pair-overlap transports.
    ///
    /// A pair-overlap map changes only which cusp semicircle parameterizes the
    /// point; its two supporting circles and the geometric point are certified
    /// identical. Peeling that wrapper is therefore sound for a rational
    /// carrier-to-carrier correspondence and avoids constructing a field for
    /// either cusp root. Other pair evidence does not retain a rational source
    /// point and deliberately remains explicit.
    fn coincident_rational_source(
        &self,
    ) -> Option<(
        &BezierAlgebraicCuspSemicircleRationalParameterMap2,
        &BezierAlgebraicCuspSemicircleRationalMapContact2,
    )> {
        match self {
            Self::Rational { map, contact } => Some((map, contact)),
            Self::PairOverlapMap { source, .. } => {
                let BezierAlgebraicCuspSemicircleParameter2::Mapped(source) = source else {
                    return None;
                };
                source.coincident_rational_source()
            }
            Self::Parallel { .. } | Self::Pair { .. } | Self::PairOverlap { .. } => None,
            Self::SelectedFiberRational { .. }
            | Self::SelectedFiberParallel { .. }
            | Self::SelectedParallelContact { .. }
            | Self::SelectedCircularTangentContact { .. }
            | Self::SelectedPairContact { .. }
            | Self::SelectedChordNormalContact { .. }
            | Self::SelectedChordParallelNormalContact { .. }
            | Self::Chord { .. }
            | Self::SimilarityTransport { .. }
            | Self::Chamfer { .. } => None,
        }
    }

    /// Recovers a pair contact beneath coincident-circle transports together
    /// with the orientation from its original carrier to the current one.
    fn coincident_pair_source(
        &self,
    ) -> Option<(
        &BezierAlgebraicCuspSemicirclePairParameterMap2,
        &BezierAlgebraicCuspSemicirclePairContact2,
        bool,
        bool,
    )> {
        match self {
            Self::Pair {
                map,
                contact,
                first,
            } => Some((map, contact, *first, false)),
            Self::PairOverlapMap {
                overlap, source, ..
            } => {
                let BezierAlgebraicCuspSemicircleParameter2::Mapped(source) = source else {
                    return None;
                };
                let (map, contact, first, reversed) = source.coincident_pair_source()?;
                Some((
                    map,
                    contact,
                    first,
                    reversed
                        ^ (overlap.data.orientation == RationalBezierOverlapOrientation2::Reversed),
                ))
            }
            Self::Rational { .. } | Self::Parallel { .. } | Self::PairOverlap { .. } => None,
            Self::SelectedFiberRational { .. }
            | Self::SelectedFiberParallel { .. }
            | Self::SelectedParallelContact { .. }
            | Self::SelectedCircularTangentContact { .. }
            | Self::SelectedPairContact { .. }
            | Self::SelectedChordNormalContact { .. }
            | Self::SelectedChordParallelNormalContact { .. }
            | Self::Chord { .. }
            | Self::SimilarityTransport { .. }
            | Self::Chamfer { .. } => None,
        }
    }

    /// Recovers a selected-circle/chord contact beneath any number of exact
    /// coincident-circle transports. The Boolean overlap orientation records
    /// whether the destination traversal tangent is reversed relative to the
    /// circle that authored the chord contact.
    fn coincident_chord_source(
        &self,
    ) -> Option<(
        &BezierAlgebraicCuspSemicircleChordParameterMap2,
        &BezierAlgebraicCuspSemicircleChordContact2,
        bool,
    )> {
        match self {
            Self::Chord { map, contact } => Some((map, contact, false)),
            Self::PairOverlapMap {
                overlap, source, ..
            } => {
                let BezierAlgebraicCuspSemicircleParameter2::Mapped(source) = source else {
                    return None;
                };
                let (map, contact, reversed) = source.coincident_chord_source()?;
                Some((
                    map,
                    contact,
                    reversed
                        ^ (overlap.data.orientation == RationalBezierOverlapOrientation2::Reversed),
                ))
            }
            Self::Rational { .. }
            | Self::SelectedFiberRational { .. }
            | Self::SelectedFiberParallel { .. }
            | Self::Parallel { .. }
            | Self::SelectedParallelContact { .. }
            | Self::SelectedCircularTangentContact { .. }
            | Self::SelectedPairContact { .. }
            | Self::SelectedChordNormalContact { .. }
            | Self::SelectedChordParallelNormalContact { .. }
            | Self::Pair { .. }
            | Self::PairOverlap { .. }
            | Self::SimilarityTransport { .. }
            | Self::Chamfer { .. } => None,
        }
    }

    /// Recovers only the chord topology needed to author an exact endpoint
    /// tangent. A represented support-line fast path deliberately keeps its
    /// point in the smaller rational map, so it carries this authority without
    /// pretending to own the full multi-field chord point system.
    fn coincident_chord_tangent_source(
        &self,
    ) -> Option<(
        &BezierAlgebraicCuspSemicircle2,
        &BezierAlgebraicChord2,
        RealSign,
        CurveContext,
        bool,
    )> {
        match self {
            Self::Rational { map, contact } => match &contact.correlation {
                BezierAlgebraicCuspSemicircleRationalCorrelation2::MapWithChordTangent {
                    chord,
                    circle_cross_chord,
                } => Some((
                    &map.data.semicircle,
                    chord,
                    *circle_cross_chord,
                    map.data.policy,
                    false,
                )),
                _ => None,
            },
            Self::Chord { map, contact } => Some((
                &map.data.semicircle,
                &map.data.chord,
                contact.tangent_cross_sign,
                map.data.policy,
                false,
            )),
            Self::SelectedChordNormalContact {
                semicircle,
                chord,
                policy,
                ..
            }
            | Self::SelectedChordParallelNormalContact {
                semicircle,
                chord,
                policy,
                ..
            } => Some((semicircle, chord, RealSign::Zero, *policy, false)),
            Self::PairOverlapMap {
                overlap,
                source,
                source_first,
            } => {
                let BezierAlgebraicCuspSemicircleParameter2::Mapped(source) = source else {
                    return None;
                };
                let (_, chord, cross, policy, reversed) =
                    source.coincident_chord_tangent_source()?;
                if policy != overlap.data.policy {
                    return None;
                }
                Some((
                    overlap.semicircle(!*source_first),
                    chord,
                    cross,
                    policy,
                    reversed
                        ^ (overlap.data.orientation == RationalBezierOverlapOrientation2::Reversed),
                ))
            }
            Self::Parallel { .. }
            | Self::SelectedFiberRational { .. }
            | Self::SelectedFiberParallel { .. }
            | Self::SelectedParallelContact { .. }
            | Self::SelectedCircularTangentContact { .. }
            | Self::SelectedPairContact { .. }
            | Self::Pair { .. }
            | Self::PairOverlap { .. }
            | Self::SimilarityTransport { .. }
            | Self::Chamfer { .. } => None,
        }
    }

    /// Returns the original one-word chord-contact parameter allocation below
    /// coincident-circle wrappers. Keeping that allocation beside the current
    /// mapped parameter preserves both the original point system and the
    /// destination selected-circle center without constructing a compositum.
    fn coincident_chord_parameter(self: &Arc<Self>) -> Option<Arc<Self>> {
        match self.as_ref() {
            Self::Chord { .. } => Some(self.clone()),
            Self::PairOverlapMap { source, .. } => {
                let BezierAlgebraicCuspSemicircleParameter2::Mapped(source) = source else {
                    return None;
                };
                source.coincident_chord_parameter()
            }
            Self::Rational { .. }
            | Self::SelectedFiberRational { .. }
            | Self::SelectedFiberParallel { .. }
            | Self::Parallel { .. }
            | Self::SelectedParallelContact { .. }
            | Self::SelectedCircularTangentContact { .. }
            | Self::SelectedPairContact { .. }
            | Self::SelectedChordNormalContact { .. }
            | Self::SelectedChordParallelNormalContact { .. }
            | Self::Pair { .. }
            | Self::PairOverlap { .. }
            | Self::SimilarityTransport { .. }
            | Self::Chamfer { .. } => None,
        }
    }

    /// Returns whether two mapped parameters name the same physical
    /// circle-circle contact, regardless of which participating semicircle
    /// owns the local parameter or how many coincident-circle transports wrap
    /// it. This identity is valid for the original contact point only; radial
    /// offsets about the two different circle centers must not reuse it.
    fn shares_coincident_pair_point(&self, other: &Self) -> bool {
        let (Some((first_map, first_contact, _, _)), Some((second_map, second_contact, _, _))) = (
            self.coincident_pair_source(),
            other.coincident_pair_source(),
        ) else {
            return false;
        };
        Arc::ptr_eq(&first_map.data, &second_map.data) && first_contact == second_contact
    }

    /// Recovers the exact endpoint carrier beneath coincident-circle overlap
    /// transports. A standalone overlap boundary is always endpoint zero or
    /// one of one participating semicircle, even when its parameter on the
    /// other carrier is non-rational.
    fn coincident_pair_endpoint_source(
        &self,
    ) -> Option<(&BezierAlgebraicCuspSemicircle2, bool, CurveContext)> {
        match self {
            Self::PairOverlap {
                overlap, endpoint, ..
            } => {
                let (semicircle, start) = match endpoint {
                    BezierAlgebraicCuspSemicirclePairEndpoint2::FirstStart => {
                        (overlap.semicircle(true), true)
                    }
                    BezierAlgebraicCuspSemicirclePairEndpoint2::FirstEnd => {
                        (overlap.semicircle(true), false)
                    }
                    BezierAlgebraicCuspSemicirclePairEndpoint2::SecondStart => {
                        (overlap.semicircle(false), true)
                    }
                    BezierAlgebraicCuspSemicirclePairEndpoint2::SecondEnd => {
                        (overlap.semicircle(false), false)
                    }
                };
                Some((semicircle, start, overlap.data.policy))
            }
            Self::PairOverlapMap { source, .. } => {
                let BezierAlgebraicCuspSemicircleParameter2::Mapped(source) = source else {
                    return None;
                };
                source.coincident_pair_endpoint_source()
            }
            Self::Rational { .. } | Self::Parallel { .. } | Self::Pair { .. } => None,
            Self::SelectedFiberRational { .. }
            | Self::SelectedFiberParallel { .. }
            | Self::SelectedParallelContact { .. }
            | Self::SelectedCircularTangentContact { .. }
            | Self::SelectedPairContact { .. }
            | Self::SelectedChordNormalContact { .. }
            | Self::SelectedChordParallelNormalContact { .. }
            | Self::Chord { .. }
            | Self::SimilarityTransport { .. }
            | Self::Chamfer { .. } => None,
        }
    }

    /// Recovers a regular mapped carrier beneath coincident-circle wrappers.
    /// Its tangent line identifies an interior point of one selected
    /// semicircle up to the antipode, which the destination overlap range
    /// excludes exactly.
    fn coincident_tangent_source(
        &self,
    ) -> Option<BezierAlgebraicCuspSemicircleMappedTangentSource2<'_>> {
        match self {
            Self::Rational { map, contact } => Some(
                BezierAlgebraicCuspSemicircleMappedTangentSource2::Rational {
                    curve: &map.data.curve,
                    parameter: &contact.other_parameter,
                    policy: map.data.policy,
                },
            ),
            Self::Parallel { map, contact } => Some(
                BezierAlgebraicCuspSemicircleMappedTangentSource2::Parallel {
                    parallel: &map.data.parallel,
                    parameter: &contact.parallel_parameter,
                    policy: map.data.policy,
                },
            ),
            Self::SelectedParallelContact {
                parallel,
                parameter,
                policy,
                ..
            } => Some(
                BezierAlgebraicCuspSemicircleMappedTangentSource2::Parallel {
                    parallel,
                    parameter,
                    policy: *policy,
                },
            ),
            Self::PairOverlapMap { source, .. } => {
                let BezierAlgebraicCuspSemicircleParameter2::Mapped(source) = source else {
                    return None;
                };
                source.coincident_tangent_source()
            }
            Self::Pair { .. } | Self::PairOverlap { .. } => None,
            Self::SelectedFiberRational { .. }
            | Self::SelectedFiberParallel { .. }
            | Self::SelectedCircularTangentContact { .. }
            | Self::SelectedPairContact { .. }
            | Self::SelectedChordNormalContact { .. }
            | Self::SelectedChordParallelNormalContact { .. }
            | Self::Chord { .. }
            | Self::SimilarityTransport { .. }
            | Self::Chamfer { .. } => None,
        }
    }

    /// Encloses a rational point whose parameter is retained directly in one
    /// selected algebraic fiber. The curve parameter and its complete reduced
    /// incidence are refined together; Cartesian evaluation then uses exact
    /// interval arithmetic and never materializes a global norm polynomial.
    fn selected_fiber_point_bounds_refined(
        &self,
        refinement_steps: usize,
        policy: &CurveContext,
    ) -> Option<Classification<Aabb2>> {
        match self {
            Self::SelectedFiberRational {
                map,
                other_parameter,
                ..
            } => Some(map.point_bounds_refined(other_parameter, refinement_steps, policy)),
            Self::SelectedFiberParallel {
                map,
                other_parameter,
                ..
            } => Some(map.point_bounds_refined(other_parameter, refinement_steps, policy)),
            _ => None,
        }
    }

    /// Encloses the point authored by an analytic-parallel map without
    /// adjoining its speed square root to the selected cusp field.
    ///
    /// The retained native parameter independently encloses every polynomial
    /// input to `P(t) + d*(-H_y,H_x)/sqrt(H dot H)`. Exact interval arithmetic
    /// therefore yields a conservative point box even when the parameter and
    /// selected circle center inhabit different fields. Refinement can prove
    /// every strict downstream order; equality remains policy-terminal.
    fn coincident_parallel_point_bounds_refined(
        &self,
        refinement_steps: usize,
        policy: &CurveContext,
    ) -> Option<Classification<Aabb2>> {
        let BezierAlgebraicCuspSemicircleMappedTangentSource2::Parallel {
            parallel,
            parameter,
            policy: source_policy,
        } = self.coincident_tangent_source()?
        else {
            return None;
        };
        if source_policy != *policy {
            return Some(Classification::Uncertain(UncertaintyReason::Unsupported));
        }
        Some(analytic_parallel_point_bounds_refined(
            parallel,
            parameter,
            &Real::zero(),
            &Real::zero(),
            &Real::zero(),
            refinement_steps,
            policy,
        ))
    }

    /// Encloses a retained circle-circle contact by refining its existing
    /// local semicircle parameter and selected center field independently.
    /// The ignored correlation only widens the box; every bound remains exact
    /// and converges to the retained pair contact without constructing a
    /// primitive element for the two cusp roots and circle-circle radical.
    fn coincident_pair_point_bounds_refined(
        &self,
        refinement_steps: usize,
        policy: &CurveContext,
    ) -> Option<Classification<Aabb2>> {
        let (map, contact, first, _) = self.coincident_pair_source()?;
        if map.data.policy != *policy {
            return Some(Classification::Uncertain(UncertaintyReason::Unsupported));
        }
        let bracket = match if first {
            map.first_contact_parameter_bracket(contact, refinement_steps)
        } else {
            map.second_contact_parameter_bracket(contact, refinement_steps)
        } {
            Ok(Classification::Decided(bracket)) => bracket,
            Ok(Classification::Uncertain(reason)) => {
                return Some(Classification::Uncertain(reason));
            }
            Err(_) => return Some(Classification::Uncertain(UncertaintyReason::Unsupported)),
        };
        let semicircle = if first {
            &map.data.first_semicircle
        } else {
            &map.data.second_semicircle
        };
        Some(semicircle.parameter_bracket_point_bounds_refined(&bracket, refinement_steps, policy))
    }

    /// Restricts the general complement predicate to analytic-parallel maps.
    /// That branch proves every equality under STRICT even when the retained
    /// construction policy is APPROXIMATE_512.
    fn parallel_complementary_to(
        &self,
        other: &Self,
        policy: &CurveContext,
    ) -> CurveResult<Option<Classification<bool>>> {
        if !matches!(
            (self, other),
            (Self::Parallel { .. }, Self::Parallel { .. })
        ) {
            return Ok(None);
        }
        Ok(Some(self.is_complementary_to(other, policy)?))
    }

    /// Proves that two mapped cuts are complementary parameters on the same
    /// selected semicircle without adjoining their carrier fields.
    fn is_complementary_to(
        &self,
        other: &Self,
        policy: &CurveContext,
    ) -> CurveResult<Classification<bool>> {
        if self.semicircle_carrier() != other.semicircle_carrier() {
            return Ok(Classification::Decided(false));
        }
        if let (
            Self::PairOverlapMap {
                overlap: first_overlap,
                source: first_source,
                source_first: first_side,
            },
            Self::PairOverlapMap {
                overlap: second_overlap,
                source: second_source,
                source_first: second_side,
            },
        ) = (self, other)
            && first_side == second_side
            && first_overlap.shares_parameter_authority(second_overlap)
            && first_overlap.has_exact_endpoint_map()
        {
            // A full coincident semicircle maps its local parameter by either
            // identity or unit complement.  Both affine involutions preserve
            // the relation u+v=1, so replay the distinct source carriers'
            // exact complement proof rather than comparing two nested fields.
            let (
                BezierAlgebraicCuspSemicircleParameter2::Mapped(first_source),
                BezierAlgebraicCuspSemicircleParameter2::Mapped(second_source),
            ) = (first_source, second_source)
            else {
                return Ok(Classification::Decided(false));
            };
            return first_source.is_complementary_to(second_source, policy);
        }
        if let (
            Self::Rational {
                map: first_map,
                contact: first_contact,
            },
            Self::Rational {
                map: second_map,
                contact: second_contact,
            },
        ) = (self, other)
        {
            match first_contact
                .other_parameter
                .same_value(&second_contact.other_parameter, policy)?
            {
                Classification::Decided(true) => {}
                Classification::Decided(false) => {
                    return Ok(Classification::Decided(false));
                }
                Classification::Uncertain(reason) => {
                    return Ok(Classification::Uncertain(reason));
                }
            }
            return rational_parameters_are_complementary_at_cut(
                first_map,
                second_map,
                &first_contact.other_parameter,
                policy,
            );
        }
        if let (
            Self::Parallel {
                map: first_map,
                contact: first_contact,
            },
            Self::Parallel {
                map: second_map,
                contact: second_contact,
            },
        ) = (self, other)
        {
            let mut uncertainty = None;
            for orientation in [
                RationalBezierOverlapOrientation2::Same,
                RationalBezierOverlapOrientation2::Reversed,
            ] {
                let second_parameter = if orientation == RationalBezierOverlapOrientation2::Same {
                    second_contact.parallel_parameter.clone()
                } else {
                    second_contact.parallel_parameter.unit_complement()
                };
                match first_contact
                    .parallel_parameter
                    .same_value(&second_parameter, &CurveContext::STRICT)?
                {
                    Classification::Decided(true) => {
                        match parallel_parameters_are_complementary_at_cut(
                            first_map,
                            second_map,
                            &first_contact.parallel_parameter,
                            orientation,
                            policy,
                        )? {
                            Classification::Decided(true) => {
                                return Ok(Classification::Decided(true));
                            }
                            Classification::Decided(false) => {}
                            Classification::Uncertain(reason) => {
                                uncertainty.get_or_insert(reason);
                            }
                        }
                    }
                    Classification::Decided(false) => {}
                    Classification::Uncertain(reason) => {
                        uncertainty.get_or_insert(reason);
                    }
                }
            }
            return Ok(
                uncertainty.map_or(Classification::Decided(false), Classification::Uncertain)
            );
        }
        let (rational_map, rational_parameter, parallel_map, parallel_parameter) =
            match (self, other) {
                (
                    Self::Rational { map, contact },
                    Self::Parallel {
                        map: parallel_map,
                        contact: parallel_contact,
                    },
                ) => (
                    map,
                    &contact.other_parameter,
                    parallel_map,
                    &parallel_contact.parallel_parameter,
                ),
                (
                    Self::Parallel {
                        map: parallel_map,
                        contact: parallel_contact,
                    },
                    Self::Rational { map, contact },
                ) => (
                    map,
                    &contact.other_parameter,
                    parallel_map,
                    &parallel_contact.parallel_parameter,
                ),
                _ => return Ok(Classification::Decided(false)),
            };
        match rational_parameter.same_value(parallel_parameter, policy)? {
            Classification::Decided(true) => {}
            Classification::Decided(false) => return Ok(Classification::Decided(false)),
            Classification::Uncertain(reason) => {
                return Ok(Classification::Uncertain(reason));
            }
        }
        rational_parallel_parameters_are_complementary_at_cut(
            rational_map,
            parallel_map,
            rational_parameter,
            policy,
        )
    }
}

