    #[test]
    fn quadratic_factor_sign_multiplies_exact_nonzero_factor_signs() {
        let negative = TrivariatePolynomial2 {
            coefficients: vec![
                vec![
                    vec![-Real::one(), -Real::one()],
                    vec![-Real::one(), Real::zero()],
                ],
                vec![
                    vec![-Real::one(), Real::zero()],
                    vec![Real::zero(), Real::zero()],
                ],
            ],
        };
        let positive = TrivariatePolynomial2 {
            coefficients: vec![
                vec![
                    vec![Real::from(2_i8), Real::zero()],
                    vec![Real::zero(), Real::one()],
                ],
                vec![
                    vec![Real::zero(), Real::one()],
                    vec![Real::one(), Real::zero()],
                ],
            ],
        };
        let polynomial = trivariate_multiply(&negative, &positive);
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let parameter = BezierParameter2::Exact(half);
        assert_eq!(
            trivariate_bounded_factor_sign(&polynomial, &parameter, &parameter, &parameter,)
                .unwrap(),
            Some(RealSign::Negative)
        );
    }

    #[test]
    fn trivariate_linear_resultant_certifies_every_axis_order() {
        let (parameters, base) = nonaffine_three_field_chord_fixture();
        for linear_axis in 0..3 {
            let mut polynomial = TrivariatePolynomial2 {
                coefficients: base.coefficients.clone(),
            };
            for nonlinear_axis in (0..3).filter(|axis| *axis != linear_axis) {
                polynomial = trivariate_multiply_axis_linear(
                    polynomial,
                    nonlinear_axis,
                    &Real::one(),
                    &Real::one(),
                );
            }
            assert_eq!(
                trivariate_parameter_triple_sign_by_refinement(
                    &polynomial,
                    &parameters[0],
                    &parameters[1],
                    &parameters[2],
                    &CurveContext::STRICT,
                )
                .unwrap(),
                Classification::Decided(RealSign::Zero),
                "linear axis {linear_axis} must certify the selected common root",
            );
        }
    }

    #[test]
    fn trivariate_linear_resultant_rejects_a_foreign_conjugate() {
        let (mut parameters, polynomial) = nonaffine_three_field_chord_fixture();
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let twenty_one_halves = (Real::from(21_i8) / Real::from(2_i8)).unwrap();
        // Multiplying gamma's defining polynomial by x^2-1/2 makes the
        // resultant vanish for the actual chord root and the foreign root
        // sqrt(1/2). The selected isolator below retains only the latter.
        let defining = match BezierParameterPolynomial::try_new_power_basis(
            vec![
                -half,
                Real::zero(),
                Real::from(6_i8),
                Real::zero(),
                -twenty_one_halves,
                Real::zero(),
                Real::one(),
            ],
            &CurveContext::STRICT,
        )
        .unwrap()
        {
            Classification::Decided(polynomial) => polynomial,
            Classification::Uncertain(reason) => panic!("foreign polynomial: {reason:?}"),
        };
        let interval = match BezierParameterInterval::try_new(
            (Real::from(2_i8) / Real::from(3_i8)).unwrap(),
            (Real::from(3_i8) / Real::from(4_i8)).unwrap(),
            &CurveContext::STRICT,
        )
        .unwrap()
        {
            Classification::Decided(interval) => interval,
            Classification::Uncertain(reason) => panic!("foreign isolator: {reason:?}"),
        };
        parameters[2] =
            match BezierAlgebraicParameter2::try_isolate(defining, interval, &CurveContext::STRICT)
                .unwrap()
            {
                Classification::Decided(parameter) => BezierParameter2::Algebraic(parameter),
                Classification::Uncertain(reason) => panic!("foreign root: {reason:?}"),
            };

        assert_ne!(
            trivariate_linear_axis_resultant_sign(
                &polynomial,
                &parameters[0],
                &parameters[1],
                &parameters[2],
            )
            .unwrap(),
            Some(RealSign::Zero),
        );
        assert_eq!(
            trivariate_parameter_triple_sign_by_refinement(
                &polynomial,
                &parameters[0],
                &parameters[1],
                &parameters[2],
                &CurveContext::STRICT,
            )
            .unwrap(),
            Classification::Decided(RealSign::Negative),
        );
    }

    #[test]
    fn trivariate_quotient_reduction_preserves_every_axis() {
        let polynomial = TrivariatePolynomial2 {
            coefficients: (0..4)
                .map(|first| {
                    (0..3)
                        .map(|second| {
                            (0..5)
                                .map(|third| {
                                    Real::from(1_i32 + first * 11 + second * 5 + third * 3)
                                })
                                .collect()
                        })
                        .collect()
                })
                .collect(),
        };
        let defining = [Real::zero(), -Real::one(), Real::one()];
        let evaluate = |polynomial: &TrivariatePolynomial2, values: &[Real; 3]| {
            polynomial
                .coefficients
                .iter()
                .rev()
                .fold(Real::zero(), |first_accumulator, rows| {
                    first_accumulator * &values[0]
                        + rows
                            .iter()
                            .rev()
                            .fold(Real::zero(), |second_accumulator, row| {
                                second_accumulator * &values[1]
                                    + polynomial_evaluate(row, &values[2])
                            })
                })
        };
        for axis in 0..3 {
            let mut values = [
                (Real::from(2_i8) / Real::from(5_i8)).unwrap(),
                (Real::from(3_i8) / Real::from(7_i8)).unwrap(),
                (Real::from(4_i8) / Real::from(9_i8)).unwrap(),
            ];
            values[axis] = Real::one();
            let reduced = trivariate_reduce_axis_mod_defining(polynomial.clone(), axis, &defining)
                .expect("the bounded quotient reduction must fit");
            let dimensions = reduced.dimensions();
            assert_eq!([dimensions.0, dimensions.1, dimensions.2][axis], 2);
            assert_eq!(evaluate(&reduced, &values), evaluate(&polynomial, &values));
        }
    }

    #[test]
    fn defining_polynomial_reduction_certifies_nonlinear_three_field_zero() {
        let (parameters, mut polynomial) = nonaffine_three_field_chord_fixture();
        for axis in 0..3 {
            polynomial =
                trivariate_multiply_axis_linear(polynomial, axis, &Real::one(), &Real::one());
        }
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                trivariate_parameter_triple_sign_by_refinement(
                    &polynomial,
                    &parameters[0],
                    &parameters[1],
                    &parameters[2],
                    attempt,
                )
                .unwrap()
            });
            assert_eq!(outcome.value, Classification::Decided(RealSign::Zero),);
            assert_eq!(outcome.certainty, crate::CurveCertainty::Certified);
        }
    }

    #[test]
    fn multiplicative_cubic_three_field_zero_is_exact_in_every_axis_order() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let third = (Real::one() / Real::from(3_i8)).unwrap();
        let sixth = (Real::one() / Real::from(6_i8)).unwrap();
        let factors = [
            algebraic_parameter(vec![-half, Real::zero(), Real::zero(), Real::one()]),
            algebraic_parameter(vec![-third, Real::zero(), Real::zero(), Real::one()]),
        ];
        let product = algebraic_parameter(vec![-sixth, Real::zero(), Real::zero(), Real::one()]);
        for product_axis in 0..3 {
            let factor_axes = (0..3)
                .filter(|axis| *axis != product_axis)
                .collect::<Vec<_>>();
            let parameters: [BezierParameter2; 3] = std::array::from_fn(|axis| {
                if axis == product_axis {
                    product.clone()
                } else if axis == factor_axes[0] {
                    factors[0].clone()
                } else {
                    factors[1].clone()
                }
            });
            // left*right-product. One nonzero linear factor per axis makes
            // the predicate quadratic in every cubic field, so independent
            // defining-polynomial reduction cannot expose a linear axis.
            let mut coefficients = vec![vec![vec![Real::zero(); 2]; 2]; 2];
            let mut factor_exponents = [0; 3];
            factor_exponents[factor_axes[0]] = 1;
            factor_exponents[factor_axes[1]] = 1;
            coefficients[factor_exponents[0]][factor_exponents[1]][factor_exponents[2]] =
                Real::one();
            let mut product_exponents = [0; 3];
            product_exponents[product_axis] = 1;
            coefficients[product_exponents[0]][product_exponents[1]][product_exponents[2]] =
                -Real::one();
            let mut polynomial = TrivariatePolynomial2 { coefficients };
            for axis in 0..3 {
                polynomial =
                    trivariate_multiply_axis_linear(polynomial, axis, &Real::one(), &Real::one());
            }
            assert!(
                trivariate_reduce_selected_root_relations(
                    &polynomial,
                    &parameters[0],
                    &parameters[1],
                    &parameters[2],
                )
                .is_none()
            );
            for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
                let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                    trivariate_parameter_triple_sign_by_refinement(
                        &polynomial,
                        &parameters[0],
                        &parameters[1],
                        &parameters[2],
                        attempt,
                    )
                    .unwrap()
                });
                assert_eq!(outcome.value, Classification::Decided(RealSign::Zero));
                assert_eq!(outcome.certainty, crate::CurveCertainty::Certified);
            }
        }
    }

    #[test]
    fn multiplicative_root_relation_rejects_a_different_selected_root() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let third = (Real::one() / Real::from(3_i8)).unwrap();
        let fifth = (Real::one() / Real::from(5_i8)).unwrap();
        let first = algebraic_parameter(vec![-half, Real::zero(), Real::zero(), Real::one()]);
        let second = algebraic_parameter(vec![-third, Real::zero(), Real::zero(), Real::one()]);
        let foreign = algebraic_parameter(vec![-fifth, Real::zero(), Real::zero(), Real::one()]);

        assert!(!exact_parameter_binary_relation(
            &first,
            &second,
            &foreign,
            hypersolve::AlgebraicRootArithmeticOp::Multiply,
        ));
    }

    #[test]
    fn square_free_cubic_lift_retains_top_slice_content() {
        let factor = trivariate_multi_affine([1, 0, 0, 1, 2, 0, 0, 1]);
        let mut quadratic_coefficients = vec![vec![vec![Real::zero(); 3]; 3]; 3];
        quadratic_coefficients[0][0][0] = Real::one();
        quadratic_coefficients[2][0][0] = Real::one();
        quadratic_coefficients[0][2][0] = Real::one();
        quadratic_coefficients[0][0][2] = Real::one();
        let product = trivariate_multiply(
            &factor,
            &TrivariatePolynomial2 {
                coefficients: quadratic_coefficients,
            },
        );
        let factorizations = trivariate_rational_multi_affine_axis_factorizations(&product, 0)
            .expect("linear top-slice content must remain attached to its factor");
        assert!(factorizations.iter().all(|(recovered, quotient)| {
            trivariate_multiply(recovered, quotient).coefficients == product.coefficients
        }));
    }

    #[test]
    fn additive_cubic_three_field_zero_is_exact_in_every_axis_order() {
        let twentieth = (Real::one() / Real::from(20_i8)).unwrap();
        let thirtieth = (Real::one() / Real::from(30_i8)).unwrap();
        let summands = [
            algebraic_parameter(vec![-twentieth, Real::zero(), Real::zero(), Real::one()]),
            algebraic_parameter(vec![-thirtieth, Real::zero(), Real::zero(), Real::one()]),
        ];
        // If a^3=1/20, b^3=1/30, and s=a+b, then
        // (s^3-1/12)^3-27*(1/600)*s^3 = 0.
        let mut sum_defining = vec![Real::zero(); 10];
        sum_defining[0] = -(Real::one() / Real::from(1728_i16)).unwrap();
        sum_defining[3] = -(Real::from(29_i8) / Real::from(1200_i16)).unwrap();
        sum_defining[6] = -(Real::one() / Real::from(4_i8)).unwrap();
        sum_defining[9] = Real::one();
        let sum = algebraic_parameter(sum_defining);
        let fifth = (Real::one() / Real::from(5_i8)).unwrap();
        let foreign = algebraic_parameter(vec![-fifth, Real::zero(), Real::zero(), Real::one()]);
        assert!(exact_parameter_binary_relation(
            &summands[0],
            &summands[1],
            &sum,
            hypersolve::AlgebraicRootArithmeticOp::Add,
        ));
        assert!(!exact_parameter_binary_relation(
            &summands[0],
            &summands[1],
            &foreign,
            hypersolve::AlgebraicRootArithmeticOp::Add,
        ));

        for sum_axis in 0..3 {
            let summand_axes = (0..3).filter(|axis| *axis != sum_axis).collect::<Vec<_>>();
            let parameters: [BezierParameter2; 3] = std::array::from_fn(|axis| {
                if axis == sum_axis {
                    sum.clone()
                } else if axis == summand_axes[0] {
                    summands[0].clone()
                } else {
                    summands[1].clone()
                }
            });
            let mut coefficients = vec![vec![vec![Real::zero(); 2]; 2]; 2];
            let mut first_exponents = [0; 3];
            first_exponents[summand_axes[0]] = 1;
            coefficients[first_exponents[0]][first_exponents[1]][first_exponents[2]] = Real::one();
            let mut second_exponents = [0; 3];
            second_exponents[summand_axes[1]] = 1;
            coefficients[second_exponents[0]][second_exponents[1]][second_exponents[2]] =
                Real::one();
            let mut sum_exponents = [0; 3];
            sum_exponents[sum_axis] = 1;
            coefficients[sum_exponents[0]][sum_exponents[1]][sum_exponents[2]] = -Real::one();
            let mut polynomial = TrivariatePolynomial2 { coefficients };
            for axis in 0..3 {
                polynomial =
                    trivariate_multiply_axis_linear(polynomial, axis, &Real::one(), &Real::one());
            }
            assert!(
                trivariate_reduce_selected_root_relations(
                    &polynomial,
                    &parameters[0],
                    &parameters[1],
                    &parameters[2],
                )
                .is_none()
            );
            for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
                let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                    trivariate_parameter_triple_sign_by_refinement(
                        &polynomial,
                        &parameters[0],
                        &parameters[1],
                        &parameters[2],
                        attempt,
                    )
                    .unwrap()
                });
                assert_eq!(outcome.value, Classification::Decided(RealSign::Zero));
                assert_eq!(outcome.certainty, crate::CurveCertainty::Certified);
            }
        }
    }

    fn nonlinear_rational_three_field_parameters() -> [BezierParameter2; 3] {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let third = (Real::one() / Real::from(3_i8)).unwrap();
        [
            algebraic_parameter(vec![-half, Real::zero(), Real::zero(), Real::one()]),
            algebraic_parameter(vec![-third, Real::zero(), Real::zero(), Real::one()]),
            // c=a*b/(a+b). From (1/c)^3=(1/a+1/b)^3, the
            // selected positive root obeys 1-15*c^3-87*c^6-125*c^9=0.
            algebraic_parameter(vec![
                Real::one(),
                Real::zero(),
                Real::zero(),
                Real::from(-15_i8),
                Real::zero(),
                Real::zero(),
                Real::from(-87_i8),
                Real::zero(),
                Real::zero(),
                Real::from(-125_i8),
            ]),
        ]
    }

    #[test]
    fn projected_three_field_candidate_retains_selected_root_correlation() {
        let parameters = nonlinear_rational_three_field_parameters();
        // c = a*b/(a+b), written without division.  The univariate norm for
        // c also contains values contributed by conjugate choices of a and b;
        // the product-box authority must retain only this selected tuple.
        let mut coefficients = vec![vec![vec![Real::zero(); 2]; 2]; 2];
        coefficients[1][1][0] = Real::one();
        coefficients[1][0][1] = -Real::one();
        coefficients[0][1][1] = -Real::one();
        let incidence = TrivariatePolynomial2 { coefficients };
        assert!(
            projected_selected_trivariate_candidate_has_box_root(
                &incidence,
                &parameters[0],
                &parameters[1],
                &parameters[2],
                8,
            )
            .unwrap()
        );

        let unrelated = algebraic_parameter(vec![
            (Real::from(-2_i8) / Real::from(5_i8)).unwrap(),
            Real::zero(),
            Real::one(),
        ]);
        assert!(
            !projected_selected_trivariate_candidate_has_box_root(
                &incidence,
                &parameters[0],
                &parameters[1],
                &unrelated,
                8,
            )
            .unwrap()
        );

        // An even-multiplicity contact has no opposite incidence-face signs;
        // it must decline this acceleration and remain exactly decidable by
        // the general authored-factor fallback.
        let tangent_incidence = trivariate_multiply(&incidence, &incidence);
        assert!(
            !projected_selected_trivariate_candidate_has_box_root(
                &tangent_incidence,
                &parameters[0],
                &parameters[1],
                &parameters[2],
                8,
            )
            .unwrap()
        );
        assert_eq!(
            trivariate_parameter_triple_sign_by_refinement(
                &tangent_incidence,
                &parameters[0],
                &parameters[1],
                &parameters[2],
                &CurveContext::STRICT,
            )
            .unwrap(),
            Classification::Decided(RealSign::Zero)
        );
    }

    #[test]
    fn selected_pair_subresultant_certifies_an_even_root_after_selected_degree_drop() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let third = (Real::one() / Real::from(3_i8)).unwrap();
        let four_fifths = (Real::from(4_i8) / Real::from(5_i8)).unwrap();
        let alpha = algebraic_parameter(vec![-half, Real::zero(), Real::one()]);
        let beta_parameters = algebraic_parameters(vec![
            &third * &four_fifths,
            Real::zero(),
            -(&third + &four_fifths),
            Real::zero(),
            Real::one(),
        ]);
        let beta = beta_parameters[0].clone();

        // P(a,b,t)=(t-a)^2+(b^2-1/3)t^3.  The cubic coefficient
        // vanishes only at beta's selected factor, not modulo beta's complete
        // reducible defining polynomial. The selected fiber is therefore a
        // tangent square even though the global tensor has neither that
        // factorization nor the same target-axis degree.
        let mut coefficients = vec![vec![vec![Real::zero(); 4]; 3]; 3];
        coefficients[0][0][2] = Real::one();
        coefficients[1][0][1] = Real::from(-2_i8);
        coefficients[2][0][0] = Real::one();
        coefficients[0][0][3] = -third;
        coefficients[0][2][3] = Real::one();
        let projected = TrivariatePolynomial2 { coefficients };
        assert!(
            !projected_selected_trivariate_candidate_has_box_root(
                &projected, &alpha, &beta, &alpha, 8,
            )
            .unwrap()
        );

        let unrelated = algebraic_parameter(vec![
            (Real::from(-2_i8) / Real::from(5_i8)).unwrap(),
            Real::zero(),
            Real::one(),
        ]);
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            assert_eq!(
                projected_selected_trivariate_candidate_has_subresultant_root(
                    &projected, &alpha, &beta, &alpha, &policy,
                )
                .unwrap(),
                Classification::Decided(true),
            );
            assert_eq!(
                projected_selected_trivariate_candidate_has_subresultant_root(
                    &projected, &alpha, &beta, &unrelated, &policy,
                )
                .unwrap(),
                Classification::Decided(false),
            );
        }
    }

    fn independent_pair_radial_unit_circle(
        policy: &CurveContext,
    ) -> BezierAlgebraicCuspSemicircle2 {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let fifth = (Real::one() / Real::from(5_i8)).unwrap();
        let two_fifths = Real::from(2_i8) * &fifth;
        // C1=(alpha,alpha), alpha^2=1/2, and
        // C2=(beta,2 beta), beta^2=1/5, are independent unit-circle
        // centers. Their lower semicircles share only the origin; their other
        // full-circle contact C1+C2 lies on both upper halves.
        let first = synthetic_selected_cusp_semicircle(
            vec![Real::zero(), Real::one()],
            vec![Real::zero(), Real::one()],
            half.clone(),
            half,
            Real::one(),
            Real::one(),
            true,
            policy,
        );
        let second = synthetic_selected_cusp_semicircle(
            vec![Real::zero(), Real::one()],
            vec![Real::zero(), Real::from(2_i8)],
            fifth,
            two_fifths,
            (Real::one() / Real::from(2_i8)).unwrap(),
            Real::one(),
            true,
            policy,
        );
        let result = first.pair_intersections(&second, policy).unwrap();
        let Classification::Decided(BezierAlgebraicCuspSemicirclePairIntersections2::Contacts {
            contacts,
            parameter_map,
        }) = result
        else {
            panic!(
                "the independent lower semicircles must retain their origin contact: {result:?}"
            );
        };
        let [center_contact] = contacts.as_slice() else {
            panic!("the lower semicircles must have exactly one contact");
        };
        assert_eq!(
            center_contact.first_location,
            BezierAlgebraicCuspSemicircleContactLocation2::Interior,
        );
        assert_eq!(
            center_contact.second_location,
            BezierAlgebraicCuspSemicircleContactLocation2::Interior,
        );
        assert_eq!(center_contact.tangent_cross_sign, RealSign::Positive);
        let center_parameter = parameter_map.first_contact_parameter(center_contact);
        let Classification::Decided(Some(circle)) =
            BezierAlgebraicCuspSemicircle2::from_selected_circle_radial(
                &first,
                center_parameter,
                Real::one(),
                Real::one(),
                false,
                policy,
            )
            .unwrap()
        else {
            panic!("the pair-native unit circle must construct");
        };
        assert!(circle.uses_selected_radial_frame());
        circle
    }

    fn recursively_pair_radial_half(policy: &CurveContext) -> BezierAlgebraicCuspSemicircle2 {
        let ninth = (Real::one() / Real::from(9_i8)).unwrap();
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let pair = independent_pair_radial_unit_circle(policy);
        let ordinary = synthetic_selected_cusp_semicircle(
            vec![Real::zero(), Real::from(3_i8)],
            vec![Real::zero()],
            ninth,
            (Real::one() / Real::from(4_i8)).unwrap(),
            half.clone(),
            Real::one(),
            true,
            policy,
        );
        let Classification::Decided(BezierAlgebraicCuspSemicirclePairIntersections2::Contacts {
            contacts,
            parameter_map,
        }) = pair.pair_intersections(&ordinary, policy).unwrap()
        else {
            panic!("the recursive frame fixture must retain its pair contact");
        };
        let [contact] = contacts.as_slice() else {
            panic!("the recursive frame fixture must have one contact");
        };
        let Classification::Decided(Some(recursive)) =
            BezierAlgebraicCuspSemicircle2::from_selected_circle_radial(
                &pair,
                parameter_map.first_contact_parameter(contact),
                Real::one(),
                half,
                false,
                policy,
            )
            .unwrap()
        else {
            panic!("the recursively pair-authored circle must construct");
        };
        recursive
    }

    /// Authors a recursive frame at the rational transverse contact `(0,-1)`.
    /// The second unit circle is centered at `(1,-1)` and its rational
    /// Pythagorean start radial selects that contact while excluding `(1,0)`.
    fn recursively_pair_radial_rational_center_half(
        policy: &CurveContext,
    ) -> BezierAlgebraicCuspSemicircle2 {
        let first = independent_pair_radial_unit_circle(policy);
        let fifth = (Real::one() / Real::from(5_i8)).unwrap();
        let second = synthetic_selected_cusp_semicircle(
            vec![Real::zero(), Real::from(3_i8)],
            vec![Real::from(-1_i8)],
            (Real::one() / Real::from(9_i8)).unwrap(),
            (Real::one() / Real::from(4_i8)).unwrap(),
            (Real::one() / Real::from(2_i8)).unwrap(),
            Real::one(),
            true,
            policy,
        );
        let second = synthetic_selected_cusp_semicircle_with_normal(
            &second,
            vec![Real::from(3_i8) * &fifth],
            vec![Real::from(-4_i8) * fifth],
        );
        let result = first.pair_intersections(&second, policy).unwrap();
        let Classification::Decided(BezierAlgebraicCuspSemicirclePairIntersections2::Contacts {
            contacts,
            parameter_map,
        }) = result
        else {
            panic!("the rational-center transverse recursive fixture must intersect: {result:?}");
        };
        let [contact] = contacts.as_slice() else {
            panic!("the rational-center transverse fixture must retain one contact: {contacts:?}");
        };
        assert_eq!(
            contact.first_location,
            BezierAlgebraicCuspSemicircleContactLocation2::Interior,
        );
        assert_eq!(
            contact.second_location,
            BezierAlgebraicCuspSemicircleContactLocation2::Interior,
        );
        let Classification::Decided(Some(recursive)) =
            BezierAlgebraicCuspSemicircle2::from_selected_circle_radial(
                &first,
                parameter_map.first_contact_parameter(contact),
                Real::one(),
                (Real::one() / Real::from(2_i8)).unwrap(),
                false,
                policy,
            )
            .unwrap()
        else {
            panic!("the rational-center transverse recursive circle must construct");
        };
        recursive
    }

    #[test]
    fn pair_radial_circle_intersects_an_ordinary_selected_circle_exactly() {
        let ninth = (Real::one() / Real::from(9_i8)).unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let pair = independent_pair_radial_unit_circle(&policy);
            // gamma^2=1/9 on the positive isolator, so this center is exactly
            // (3*gamma,0)=(1,0) while retaining an independent selected root.
            let ordinary = synthetic_selected_cusp_semicircle(
                vec![Real::zero(), Real::from(3_i8)],
                vec![Real::zero()],
                ninth.clone(),
                (Real::one() / Real::from(4_i8)).unwrap(),
                (Real::one() / Real::from(2_i8)).unwrap(),
                Real::one(),
                true,
                &policy,
            );
            for (first, second, expected_tangent) in [
                (&pair, &ordinary, RealSign::Positive),
                (&ordinary, &pair, RealSign::Negative),
            ] {
                let result = first.pair_intersections(second, &policy).unwrap();
                let Classification::Decided(
                    BezierAlgebraicCuspSemicirclePairIntersections2::Contacts {
                        contacts,
                        parameter_map,
                    },
                ) = result
                else {
                    panic!("the three-root circle pair must complete: {result:?}");
                };
                let [contact] = contacts.as_slice() else {
                    panic!("the two selected halves must retain one contact: {contacts:?}");
                };
                assert_eq!(
                    contact.first_location,
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(
                    contact.second_location,
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(contact.tangent_cross_sign, expected_tangent);
                assert_eq!(
                    parameter_map.tangent_dot_sign(contact, &policy).unwrap(),
                    Classification::Decided(RealSign::Negative),
                );
                let represented = parameter_map
                    .represented_selected_radial_contact_point(contact)
                    .unwrap();
                let Classification::Decided([represented_x, represented_y]) = represented else {
                    panic!("the three-root contact must materialize exactly: {represented:?}");
                };
                assert!(represented_x.is_valid());
                assert!(represented_y.is_valid());
                let half = (Real::one() / Real::from(2_i8)).unwrap();
                assert!(matches!(
                    compare_reals(&represented_x.interval.lower, &half, &CurveContext::STRICT),
                    Some(std::cmp::Ordering::Less | std::cmp::Ordering::Equal),
                ));
                assert!(matches!(
                    compare_reals(&represented_x.interval.upper, &half, &CurveContext::STRICT),
                    Some(std::cmp::Ordering::Greater | std::cmp::Ordering::Equal),
                ));
                assert_eq!(
                    compare_reals(
                        &represented_y.interval.upper,
                        &Real::zero(),
                        &CurveContext::STRICT,
                    ),
                    Some(std::cmp::Ordering::Less),
                );
                let first_parameter = parameter_map.first_contact_parameter(contact);
                let second_parameter = parameter_map.second_contact_parameter(contact);
                for parameter in [&first_parameter, &second_parameter] {
                    assert_eq!(
                        parameter.order_to_real(&Real::zero(), &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Greater),
                    );
                    assert_eq!(
                        parameter.order_to_real(&Real::one(), &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Less),
                    );
                }
                let pair_first = first.uses_selected_radial_frame();
                let pair_parameter = if pair_first {
                    parameter_map.first_contact_parameter(contact)
                } else {
                    parameter_map.second_contact_parameter(contact)
                };
                let Classification::Decided(Some(
                    RationalBezierIntersectionPointEvidence2::AlgebraicCuspChordDerived(point),
                )) = pair_parameter
                    .coincident_point_evidence(&pair, &policy)
                    .unwrap()
                else {
                    panic!("the pair-radial side must retain its mapped point evidence");
                };
                let bounds = point.conservative_bounds_refined(64, &policy);
                assert!(matches!(bounds, Classification::Decided(_)), "{bounds:?}");
                assert_eq!(
                    point
                        .axis_coordinate_order_to_real(Axis2::X, &Real::zero(), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Greater),
                );
                assert_eq!(
                    point
                        .axis_coordinate_order_to_real(Axis2::Y, &Real::zero(), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Less),
                );
                if policy == CurveContext::STRICT {
                    assert_eq!(
                        point
                            .axis_coordinate_order_to_real(
                                Axis2::X,
                                &(Real::one() / Real::from(2_i8)).unwrap(),
                                &policy,
                            )
                            .unwrap(),
                        Classification::Decided(std::cmp::Ordering::Equal),
                    );
                }
                if pair_first {
                    let BezierAlgebraicCuspSemicircleParameter2::Mapped(mapped_parameter) =
                        pair_parameter
                    else {
                        panic!("the selected-radial contact parameter must remain mapped");
                    };
                    let rotated = BezierAlgebraicCuspChordDerivedPoint2::rotated_from_mapped_source(
                        mapped_parameter,
                        RationalBezierIntersectionPointEvidence2::AlgebraicCuspChordDerived(point),
                        Real::zero(),
                        Real::one(),
                    );
                    let represented = rotated.represented_coordinates(&policy).unwrap();
                    let Classification::Decided(Some([rotated_x, rotated_y])) = represented else {
                        panic!("the perpendicular pair image must materialize: {represented:?}");
                    };
                    assert_eq!(
                        compare_reals(
                            &rotated_x.interval.lower,
                            &Real::zero(),
                            &CurveContext::STRICT,
                        ),
                        Some(std::cmp::Ordering::Greater),
                    );
                    assert!(matches!(
                        compare_reals(&rotated_y.interval.lower, &half, &CurveContext::STRICT),
                        Some(std::cmp::Ordering::Less | std::cmp::Ordering::Equal),
                    ));
                    assert!(matches!(
                        compare_reals(&rotated_y.interval.upper, &half, &CurveContext::STRICT),
                        Some(std::cmp::Ordering::Greater | std::cmp::Ordering::Equal),
                    ));
                }
            }
        }
    }

    #[test]
    fn recursively_pair_radial_circle_materializes_its_exact_frame() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let encloses = |representation: &AlgebraicRootRepresentation, value: &Real| {
            compare_reals(&representation.interval.lower, value, &CurveContext::STRICT)
                != Some(std::cmp::Ordering::Greater)
                && compare_reals(&representation.interval.upper, value, &CurveContext::STRICT)
                    != Some(std::cmp::Ordering::Less)
        };
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let recursive = recursively_pair_radial_half(&policy);
            assert!(matches!(
                recursive.selected_radial_frame_system(&policy).unwrap(),
                Classification::Uncertain(UncertaintyReason::Unsupported),
            ));
            let frame = recursive
                .represented_selected_radial_frame(&policy)
                .unwrap();
            let Classification::Decided(frame) = frame else {
                panic!("the recursive selected-radial frame must materialize: {frame:?}");
            };
            assert!(encloses(&frame.center[0], &half));
            assert!(encloses(&frame.unit_radial[0], &half));
            assert_eq!(
                compare_reals(
                    &frame.center[1].interval.upper,
                    &Real::zero(),
                    &CurveContext::STRICT,
                ),
                Some(std::cmp::Ordering::Less),
            );
            assert_eq!(
                compare_reals(
                    &frame.unit_radial[1].interval.upper,
                    &Real::zero(),
                    &CurveContext::STRICT,
                ),
                Some(std::cmp::Ordering::Less),
            );

            let translate = Similarity2::try_from_real_affine(
                Real::one(),
                Real::zero(),
                Real::zero(),
                Real::one(),
                Real::one(),
                Real::zero(),
            )
            .unwrap();
            let translated = recursive.transform_similarity(&translate).unwrap();
            let translated = translated
                .represented_selected_radial_frame(&policy)
                .unwrap();
            let Classification::Decided(translated) = translated else {
                panic!("the translated recursive frame must materialize: {translated:?}");
            };
            assert!(encloses(
                &translated.center[0],
                &(Real::from(3_i8) / Real::from(2_i8)).unwrap(),
            ));
            assert!(encloses(&translated.unit_radial[0], &half));
        }
    }

    #[test]
    fn recursively_pair_radial_circles_intersect_and_recurse_exactly() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let three_quarters = (Real::from(3_i8) / Real::from(4_i8)).unwrap();
        let seven_eighths = (Real::from(7_i8) / Real::from(8_i8)).unwrap();
        let translate = Similarity2::try_from_real_affine(
            Real::one(),
            Real::zero(),
            Real::zero(),
            Real::one(),
            three_quarters.clone(),
            Real::zero(),
        )
        .unwrap();
        let encloses = |representation: &AlgebraicRootRepresentation, value: &Real| {
            compare_reals(&representation.interval.lower, value, &CurveContext::STRICT)
                != Some(std::cmp::Ordering::Greater)
                && compare_reals(&representation.interval.upper, value, &CurveContext::STRICT)
                    != Some(std::cmp::Ordering::Less)
        };

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let recursive = recursively_pair_radial_half(&policy);
            // The two radius-1/2 supports are 3/4 apart. Their aligned radial
            // frames select both transverse contacts on complementary halves.
            let first = recursive.clone();
            let second = recursive
                .transform_similarity(&translate)
                .unwrap()
                .complementary_half();
            let result = first.pair_intersections(&second, &policy).unwrap();
            let Classification::Decided(
                BezierAlgebraicCuspSemicirclePairIntersections2::Contacts {
                    contacts,
                    parameter_map,
                },
            ) = result
            else {
                panic!("the recursive circle pair must complete exactly: {result:?}");
            };
            assert_eq!(contacts.len(), 2, "both transverse contacts must remain");
            for (contact, tangent_cross_sign) in contacts
                .iter()
                .zip([RealSign::Negative, RealSign::Positive])
            {
                assert_eq!(
                    contact.first_location,
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(
                    contact.second_location,
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(contact.tangent_cross_sign, tangent_cross_sign);
                assert_eq!(
                    parameter_map.tangent_dot_sign(contact, &policy).unwrap(),
                    Classification::Decided(RealSign::Negative),
                );
                let Classification::Decided([x, y]) = parameter_map
                    .represented_selected_radial_contact_point(contact)
                    .unwrap()
                else {
                    panic!("the recursive pair contact must retain exact coordinates");
                };
                assert!(encloses(&x, &seven_eighths));
                assert_eq!(
                    compare_reals(&y.interval.upper, &Real::zero(), &CurveContext::STRICT),
                    Some(std::cmp::Ordering::Less),
                );
                let first_parameter = parameter_map.first_contact_parameter(contact);
                let second_parameter = parameter_map.second_contact_parameter(contact);
                for parameter in [&first_parameter, &second_parameter] {
                    assert_eq!(
                        parameter.order_to_real(&Real::zero(), &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Greater),
                    );
                    assert_eq!(
                        parameter.order_to_real(&Real::one(), &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Less),
                    );
                }
                let first_half_order = if contact.branch < 0 {
                    std::cmp::Ordering::Less
                } else {
                    std::cmp::Ordering::Greater
                };
                assert_eq!(
                    first_parameter.order_to_real(&half, &policy).unwrap(),
                    Classification::Decided(first_half_order),
                );
                assert_eq!(
                    second_parameter.order_to_real(&half, &policy).unwrap(),
                    Classification::Decided(first_half_order.reverse()),
                );
            }

            // A represented pair map must itself remain a valid author for
            // the next selected-radial construction layer.
            let contact = contacts
                .iter()
                .find(|contact| contact.branch == -1)
                .expect("the lower support branch must remain");
            let Classification::Decided(Some(next)) =
                BezierAlgebraicCuspSemicircle2::from_selected_circle_radial(
                    &first,
                    parameter_map.first_contact_parameter(contact),
                    half.clone(),
                    quarter.clone(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the represented recursive contact must author another circle");
            };
            let Classification::Decided(frame) =
                next.represented_selected_radial_frame(&policy).unwrap()
            else {
                panic!("the next recursive frame must materialize exactly");
            };
            assert!(encloses(&frame.center[0], &seven_eighths));
            assert!(encloses(&frame.unit_radial[0], &three_quarters));
            assert_eq!(
                compare_reals(
                    &frame.center[1].interval.upper,
                    &Real::zero(),
                    &CurveContext::STRICT,
                ),
                Some(std::cmp::Ordering::Less),
            );
        }
    }

    #[test]
    fn independently_encoded_recursive_circles_intersect_and_recurse_exactly() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let three_quarters = (Real::from(3_i8) / Real::from(4_i8)).unwrap();
        let seven_eighths = (Real::from(7_i8) / Real::from(8_i8)).unwrap();
        let translate = Similarity2::try_from_real_affine(
            Real::one(),
            Real::zero(),
            Real::zero(),
            Real::one(),
            three_quarters.clone(),
            Real::zero(),
        )
        .unwrap();
        let encloses = |representation: &AlgebraicRootRepresentation, value: &Real| {
            compare_reals(&representation.interval.lower, value, &CurveContext::STRICT)
                != Some(std::cmp::Ordering::Greater)
                && compare_reals(&representation.interval.upper, value, &CurveContext::STRICT)
                    != Some(std::cmp::Ordering::Less)
        };

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            // Constructing each side independently prevents pair-map identity
            // from selecting the structural translation fast path. The
            // represented authority must instead replay the rational-affine
            // center relations before using the exact-radial circle formula.
            let first = recursively_pair_radial_half(&policy);
            let second = recursively_pair_radial_half(&policy)
                .transform_similarity(&translate)
                .unwrap()
                .complementary_half();
            let result = first.pair_intersections(&second, &policy).unwrap();
            let Classification::Decided(
                BezierAlgebraicCuspSemicirclePairIntersections2::Contacts {
                    contacts,
                    parameter_map,
                },
            ) = result
            else {
                panic!("the independently encoded recursive pair must complete: {result:?}");
            };
            assert_eq!(contacts.len(), 2, "both transverse contacts must remain");
            for (contact, tangent_cross_sign) in contacts
                .iter()
                .zip([RealSign::Negative, RealSign::Positive])
            {
                assert_eq!(
                    contact.first_location,
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(
                    contact.second_location,
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(contact.tangent_cross_sign, tangent_cross_sign);
                assert_eq!(
                    parameter_map.tangent_dot_sign(contact, &policy).unwrap(),
                    Classification::Decided(RealSign::Negative),
                );
                let Classification::Decided([x, y]) = parameter_map
                    .represented_selected_radial_contact_point(contact)
                    .unwrap()
                else {
                    panic!("the independent recursive contact must retain exact coordinates");
                };
                assert!(encloses(&x, &seven_eighths));
                assert_eq!(
                    compare_reals(&y.interval.upper, &Real::zero(), &CurveContext::STRICT),
                    Some(std::cmp::Ordering::Less),
                );
                let first_parameter = parameter_map.first_contact_parameter(contact);
                let second_parameter = parameter_map.second_contact_parameter(contact);
                for parameter in [&first_parameter, &second_parameter] {
                    assert_eq!(
                        parameter.order_to_real(&Real::zero(), &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Greater),
                    );
                    assert_eq!(
                        parameter.order_to_real(&Real::one(), &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Less),
                    );
                }
                let first_half_order = if contact.branch < 0 {
                    std::cmp::Ordering::Less
                } else {
                    std::cmp::Ordering::Greater
                };
                assert_eq!(
                    first_parameter.order_to_real(&half, &policy).unwrap(),
                    Classification::Decided(first_half_order),
                );
                assert_eq!(
                    second_parameter.order_to_real(&half, &policy).unwrap(),
                    Classification::Decided(first_half_order.reverse()),
                );
            }

            let contact = contacts
                .iter()
                .find(|contact| contact.branch == -1)
                .expect("the lower support branch must remain");
            let Classification::Decided(Some(next)) =
                BezierAlgebraicCuspSemicircle2::from_selected_circle_radial(
                    &first,
                    parameter_map.first_contact_parameter(contact),
                    half.clone(),
                    quarter.clone(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the independent represented contact must author another circle");
            };
            let Classification::Decided(frame) =
                next.represented_selected_radial_frame(&policy).unwrap()
            else {
                panic!("the independently authored recursive frame must materialize exactly");
            };
            assert!(encloses(&frame.center[0], &seven_eighths));
            assert!(encloses(&frame.unit_radial[0], &three_quarters));
            assert_eq!(
                compare_reals(
                    &frame.center[1].interval.upper,
                    &Real::zero(),
                    &CurveContext::STRICT,
                ),
                Some(std::cmp::Ordering::Less),
            );
        }
    }

