    #[test]
    fn independently_pair_radial_circles_intersect_exactly() {
        let translate = Similarity2::try_from_real_affine(
            Real::one(),
            Real::zero(),
            Real::zero(),
            Real::one(),
            Real::one(),
            Real::zero(),
        )
        .unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let first = independent_pair_radial_unit_circle(&policy);
            let second = independent_pair_radial_unit_circle(&policy)
                .transform_similarity(&translate)
                .unwrap();
            for circle in [&first, &second] {
                assert!(
                    matches!(
                        circle.represented_circle_frame(&policy),
                        Ok(Classification::Decided(_))
                    ),
                    "the selected-radial circle must materialize its exact represented frame",
                );
            }
            for (left, right, expected_tangent_cross) in [
                (&first, &second, RealSign::Negative),
                (&second, &first, RealSign::Positive),
            ] {
                let result = left.pair_intersections(right, &policy).unwrap();
                let Classification::Decided(
                    BezierAlgebraicCuspSemicirclePairIntersections2::Contacts {
                        contacts,
                        parameter_map,
                    },
                ) = result
                else {
                    panic!("the four-root selected-radial pair must complete: {result:?}");
                };
                let [contact] = contacts.as_slice() else {
                    panic!("the selected halves must retain one contact: {contacts:?}");
                };
                assert_eq!(
                    contact.first_location,
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(
                    contact.second_location,
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(contact.tangent_cross_sign, expected_tangent_cross);
                assert_eq!(
                    parameter_map.tangent_dot_sign(contact, &policy).unwrap(),
                    Classification::Decided(RealSign::Positive),
                );
                let represented = parameter_map
                    .represented_selected_radial_contact_point(contact)
                    .unwrap();
                let Classification::Decided([represented_x, represented_y]) = represented else {
                    panic!("the four-root contact must materialize exactly: {represented:?}");
                };
                assert!(represented_x.is_valid());
                assert!(represented_y.is_valid());
                let half = (Real::one() / Real::from(2_i8)).unwrap();
                assert!(matches!(
                    compare_reals(&represented_x.interval.lower, &half, &CurveContext::STRICT),
                    Some(std::cmp::Ordering::Less | std::cmp::Ordering::Equal),
                ));
                assert!(matches!(
                    compare_reals(&represented_x.interval.upper, &half, &CurveContext::STRICT),
                    Some(std::cmp::Ordering::Greater | std::cmp::Ordering::Equal),
                ));
                assert_eq!(
                    compare_reals(
                        &represented_y.interval.upper,
                        &Real::zero(),
                        &CurveContext::STRICT,
                    ),
                    Some(std::cmp::Ordering::Less),
                );
                for parameter in [
                    parameter_map.first_contact_parameter(contact),
                    parameter_map.second_contact_parameter(contact),
                ] {
                    assert_eq!(
                        parameter.order_to_real(&Real::zero(), &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Greater),
                    );
                    assert_eq!(
                        parameter.order_to_real(&Real::one(), &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Less),
                    );
                }
                let parameter = parameter_map.first_contact_parameter(contact);
                let Classification::Decided(Some(
                    RationalBezierIntersectionPointEvidence2::AlgebraicCuspChordDerived(point),
                )) = parameter.coincident_point_evidence(left, &policy).unwrap()
                else {
                    panic!("the selected-radial pair must retain mapped point evidence");
                };
                assert!(matches!(
                    point.conservative_bounds_refined(64, &policy),
                    Classification::Decided(_)
                ));
                assert_eq!(
                    point
                        .axis_coordinate_order_to_real(Axis2::Y, &Real::zero(), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Less),
                );
                if policy == CurveContext::STRICT {
                    assert_eq!(
                        point
                            .axis_coordinate_order_to_real(
                                Axis2::X,
                                &(Real::one() / Real::from(2_i8)).unwrap(),
                                &policy,
                            )
                            .unwrap(),
                        Classification::Decided(std::cmp::Ordering::Equal),
                    );
                }
            }
        }
    }

    #[test]
    fn independently_pair_radial_circles_handle_tangent_disjoint_and_concentric_supports() {
        let transform = |scale: i8, translation_x: i8, half_turn: bool| {
            let scale = if half_turn { -scale } else { scale };
            Similarity2::try_from_real_affine(
                Real::from(scale),
                Real::zero(),
                Real::zero(),
                Real::from(scale),
                Real::from(translation_x),
                Real::zero(),
            )
            .unwrap()
        };
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let first = independent_pair_radial_unit_circle(&policy);
            let tangent = independent_pair_radial_unit_circle(&policy)
                .transform_similarity(&transform(1, 2, true))
                .unwrap();
            for (left, right) in [(&first, &tangent), (&tangent, &first)] {
                let result = left.pair_intersections(right, &policy).unwrap();
                let Classification::Decided(
                    BezierAlgebraicCuspSemicirclePairIntersections2::Contacts {
                        contacts,
                        parameter_map,
                    },
                ) = result
                else {
                    panic!("the four-root circle tangency must complete: {result:?}");
                };
                let [contact] = contacts.as_slice() else {
                    panic!("externally tangent circles must retain one contact: {contacts:?}");
                };
                assert_eq!(contact.branch, 0);
                assert_eq!(contact.tangent_cross_sign, RealSign::Zero);
                assert_eq!(
                    parameter_map.tangent_dot_sign(contact, &policy).unwrap(),
                    Classification::Decided(RealSign::Negative),
                );
            }

            let disjoint = independent_pair_radial_unit_circle(&policy)
                .transform_similarity(&transform(1, 3, false))
                .unwrap();
            let concentric_unequal = independent_pair_radial_unit_circle(&policy)
                .transform_similarity(&transform(2, 0, false))
                .unwrap();
            for other in [&disjoint, &concentric_unequal] {
                for (left, right) in [(&first, other), (other, &first)] {
                    assert!(matches!(
                        left.pair_intersections(right, &policy).unwrap(),
                        Classification::Decided(
                            BezierAlgebraicCuspSemicirclePairIntersections2::NoContacts
                        )
                    ));
                }
            }
        }
    }

    #[test]
    fn independently_pair_radial_circles_map_all_coincident_half_relations() {
        let quarter_turn = Similarity2::try_from_real_affine(
            Real::zero(),
            Real::from(-1_i8),
            Real::one(),
            Real::zero(),
            Real::zero(),
            Real::zero(),
        )
        .unwrap();
        let half_turn = Similarity2::try_from_real_affine(
            Real::from(-1_i8),
            Real::zero(),
            Real::zero(),
            Real::from(-1_i8),
            Real::zero(),
            Real::zero(),
        )
        .unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let first = independent_pair_radial_unit_circle(&policy);
            let aligned = independent_pair_radial_unit_circle(&policy);
            for (left, right) in [(&first, &aligned), (&aligned, &first)] {
                let result = left.pair_intersections(right, &policy).unwrap();
                let Classification::Decided(
                    BezierAlgebraicCuspSemicirclePairIntersections2::Overlap(overlap),
                ) = result
                else {
                    panic!("independently authored aligned halves must overlap: {result:?}");
                };
                assert!(overlap.has_exact_endpoint_map());
                assert_eq!(
                    overlap.orientation(),
                    RationalBezierOverlapOrientation2::Same,
                );
            }

            let partial = independent_pair_radial_unit_circle(&policy)
                .transform_similarity(&quarter_turn)
                .unwrap();
            for (left, right) in [(&first, &partial), (&partial, &first)] {
                let result = left.pair_intersections(right, &policy).unwrap();
                let Classification::Decided(
                    BezierAlgebraicCuspSemicirclePairIntersections2::Overlap(overlap),
                ) = result
                else {
                    panic!("quarter-turned selected halves must partially overlap: {result:?}");
                };
                assert!(!overlap.has_exact_endpoint_map());
                assert_eq!(
                    overlap.orientation(),
                    RationalBezierOverlapOrientation2::Same,
                );
                for parameter in [
                    overlap.first_start_parameter(),
                    overlap.first_end_parameter(),
                    overlap.second_start_parameter(),
                    overlap.second_end_parameter(),
                ] {
                    assert!(matches!(
                        parameter.parameter_bracket(16, &policy).unwrap(),
                        Classification::Decided(_)
                    ));
                }
            }

            let antipodal = independent_pair_radial_unit_circle(&policy)
                .transform_similarity(&half_turn)
                .unwrap();
            for (left, right) in [(&first, &antipodal), (&antipodal, &first)] {
                let result = left.pair_intersections(right, &policy).unwrap();
                let Classification::Decided(
                    BezierAlgebraicCuspSemicirclePairIntersections2::EndpointContacts(contacts),
                ) = result
                else {
                    panic!("antipodal selected halves must meet only at endpoints: {result:?}");
                };
                assert_eq!(contacts.len(), 2);
            }
        }
    }

    #[test]
    fn pair_radial_circle_intersects_independent_field_chord_exactly() {
        let selected_parameter = |denominator: i8| {
            let constant = -(Real::one() / Real::from(denominator)).unwrap();
            let BezierParameter2::Algebraic(parameter) =
                algebraic_parameter(vec![constant, Real::zero(), Real::one()])
            else {
                panic!("the independent chord root must remain algebraic");
            };
            parameter
        };
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let start_parameter = selected_parameter(5);
            let end_parameter = selected_parameter(7);
            let point =
                |parameter: &BezierAlgebraicParameter2, x: Vec<Real>, y: Vec<Real>, label| {
                    RationalBezierIntersectionPointEvidence2::Algebraic(
                        RationalBezierAlgebraicPointImage2::from_retained_expression(
                            parameter.clone(),
                            parameter_representation(parameter, &policy),
                            x,
                            y,
                            vec![Real::one()],
                            label,
                        ),
                    )
                };
            let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
                point(
                    &start_parameter,
                    vec![Real::from(-3_i8), Real::one()],
                    vec![Real::from(-3_i8)],
                    "pair-radial independent chord start",
                ),
                point(
                    &end_parameter,
                    vec![Real::from(3_i8)],
                    vec![Real::from(3_i8), Real::one()],
                    "pair-radial independent chord end",
                ),
                &policy,
            )
            .unwrap() else {
                panic!("the independent pair-radial chord must construct");
            };
            assert!(chord.certified_axis_direction().is_none());
            assert!(chord.exact_line().is_none());
            assert!(chord.strict_provenance_support_line(&policy).is_none());
            let circle = independent_pair_radial_unit_circle(&policy);

            for (carrier, expected_tangent_sign) in [
                (chord.clone(), RealSign::Positive),
                (chord.reversed(), RealSign::Negative),
            ] {
                let result = circle.chord_intersections(&carrier, &policy).unwrap();
                let Classification::Decided(
                    BezierAlgebraicCuspSemicircleRetainedChordIntersections2::Contacts(contacts),
                ) = result
                else {
                    panic!("the four-field pair-radial chord must complete: {result:?}");
                };
                let [contact] = contacts.as_slice() else {
                    panic!("the selected semicircle must retain one contact: {contacts:?}");
                };
                assert_eq!(contact.tangent_cross_sign, expected_tangent_sign);
                assert_eq!(
                    contact
                        .cusp_parameter
                        .order_to_real(&Real::zero(), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Greater),
                );
                assert_eq!(
                    contact
                        .cusp_parameter
                        .order_to_real(&Real::one(), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Less),
                );
                assert_eq!(
                    contact
                        .chord_parameter
                        .cmp_by_refinement(&carrier.start_parameter(), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Greater),
                );
                assert_eq!(
                    contact
                        .chord_parameter
                        .cmp_by_refinement(&carrier.end_parameter(), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Less),
                );
                let RationalBezierIntersectionPointEvidence2::AlgebraicCuspChord(point) =
                    &contact.point
                else {
                    panic!("the four-field contact must retain its exact chord map");
                };
                for axis in [Axis2::X, Axis2::Y] {
                    assert_eq!(
                        point
                            .axis_coordinate_order_to_real(axis, &Real::from(-1_i8), &policy)
                            .unwrap(),
                        Classification::Decided(std::cmp::Ordering::Greater),
                    );
                    assert_eq!(
                        point
                            .axis_coordinate_order_to_real(axis, &Real::zero(), &policy)
                            .unwrap(),
                        Classification::Decided(std::cmp::Ordering::Less),
                    );
                }
                assert!(matches!(
                    point.conservative_bounds_refined(16, &policy),
                    Classification::Decided(_)
                ));
                if expected_tangent_sign == RealSign::Positive && policy == CurveContext::STRICT {
                    let derived = point
                        .radial_scaled(Real::one())
                        .translated(&Real::from(10_i8), &Real::from(-7_i8));
                    assert_eq!(
                        derived
                            .concentric_circle_incidence_sign(&circle, &policy)
                            .unwrap(),
                        Classification::Decided(Some(RealSign::Positive)),
                    );
                    assert_eq!(
                        derived
                            .axis_coordinate_order_to_real(Axis2::X, &Real::from(9_i8), &policy)
                            .unwrap(),
                        Classification::Decided(std::cmp::Ordering::Greater),
                    );
                    assert_eq!(
                        derived
                            .axis_coordinate_order_to_real(Axis2::Y, &Real::from(-7_i8), &policy)
                            .unwrap(),
                        Classification::Decided(std::cmp::Ordering::Less),
                    );
                    assert!(matches!(
                        derived.conservative_bounds_refined(16, &policy),
                        Classification::Decided(_)
                    ));
                }
            }
        }
    }

    #[test]
    fn pair_radial_circle_retains_independent_field_chord_tangency() {
        let selected_parameter = |denominator: i8| {
            let constant = -(Real::one() / Real::from(denominator)).unwrap();
            let BezierParameter2::Algebraic(parameter) =
                algebraic_parameter(vec![constant, Real::zero(), Real::one()])
            else {
                panic!("the tangent endpoint root must remain algebraic");
            };
            parameter
        };
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let first = selected_parameter(2);
            let second = selected_parameter(7);
            let point =
                |parameter: &BezierAlgebraicParameter2, x: Vec<Real>, y: Vec<Real>, label| {
                    RationalBezierIntersectionPointEvidence2::Algebraic(
                        RationalBezierAlgebraicPointImage2::from_retained_expression(
                            parameter.clone(),
                            parameter_representation(parameter, &policy),
                            x,
                            y,
                            vec![Real::one()],
                            label,
                        ),
                    )
                };
            let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
                point(
                    &first,
                    vec![Real::zero(), Real::from(3_i8)],
                    vec![Real::zero()],
                    "pair-radial tangent chord start",
                ),
                point(
                    &second,
                    vec![Real::zero()],
                    vec![Real::zero(), Real::from(-3_i8)],
                    "pair-radial tangent chord end",
                ),
                &policy,
            )
            .unwrap() else {
                panic!("the independent tangent chord must construct");
            };
            assert!(chord.certified_axis_direction().is_none());
            assert!(chord.exact_line().is_none());
            assert!(chord.strict_provenance_support_line(&policy).is_none());
            let circle = independent_pair_radial_unit_circle(&policy);
            let expected = Point2::new(
                (Real::from(2_i8).sqrt().unwrap() / Real::from(3_i8)).unwrap(),
                -(Real::from(7_i8).sqrt().unwrap() / Real::from(3_i8)).unwrap(),
            );

            for carrier in [chord.clone(), chord.reversed()] {
                let result = circle.chord_intersections(&carrier, &policy).unwrap();
                let Classification::Decided(
                    BezierAlgebraicCuspSemicircleRetainedChordIntersections2::Contacts(contacts),
                ) = result
                else {
                    panic!("the exact four-field tangency must complete: {result:?}");
                };
                let [contact] = contacts.as_slice() else {
                    panic!("the tangent support must retain one contact: {contacts:?}");
                };
                assert_eq!(contact.tangent_cross_sign, RealSign::Zero);
                assert_eq!(
                    contact
                        .chord_parameter
                        .cmp_by_refinement(&carrier.start_parameter(), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Greater),
                );
                assert_eq!(
                    contact
                        .chord_parameter
                        .cmp_by_refinement(&carrier.end_parameter(), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Less),
                );
                assert_eq!(
                    contact.point.same_point(
                        &RationalBezierIntersectionPointEvidence2::Exact(expected.clone()),
                        &policy,
                    ),
                    Classification::Decided(true),
                );
            }
        }
    }

    #[test]
    fn pair_radial_circle_rejects_disjoint_and_finitely_clipped_four_field_chords() {
        let selected_parameter = |denominator: i8| {
            let constant = -(Real::one() / Real::from(denominator)).unwrap();
            let BezierParameter2::Algebraic(parameter) =
                algebraic_parameter(vec![constant, Real::zero(), Real::one()])
            else {
                panic!("the chord endpoint root must remain algebraic");
            };
            parameter
        };
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let first = selected_parameter(5);
            let second = selected_parameter(7);
            let point =
                |parameter: &BezierAlgebraicParameter2, x: Vec<Real>, y: Vec<Real>, label| {
                    RationalBezierIntersectionPointEvidence2::Algebraic(
                        RationalBezierAlgebraicPointImage2::from_retained_expression(
                            parameter.clone(),
                            parameter_representation(parameter, &policy),
                            x,
                            y,
                            vec![Real::one()],
                            label,
                        ),
                    )
                };
            let chord = |start_x, start_y, end_x, end_y, start_label, end_label| {
                let Classification::Decided(chord) = BezierAlgebraicChord2::try_new(
                    point(&first, start_x, start_y, start_label),
                    point(&second, end_x, end_y, end_label),
                    &policy,
                )
                .unwrap() else {
                    panic!("the four-field rejection chord must construct");
                };
                assert!(chord.exact_line().is_none());
                assert!(chord.strict_provenance_support_line(&policy).is_none());
                chord
            };
            let disjoint = chord(
                vec![Real::from(-3_i8), Real::one()],
                vec![Real::from(3_i8)],
                vec![Real::from(3_i8)],
                vec![Real::from(3_i8), Real::one()],
                "pair-radial disjoint chord start",
                "pair-radial disjoint chord end",
            );
            let clipped = chord(
                vec![Real::from(3_i8), Real::one()],
                vec![Real::zero(), Real::one()],
                vec![Real::from(4_i8)],
                vec![Real::zero(), Real::one()],
                "pair-radial clipped chord start",
                "pair-radial clipped chord end",
            );
            let circle = independent_pair_radial_unit_circle(&policy);
            for carrier in [
                disjoint.clone(),
                disjoint.reversed(),
                clipped.clone(),
                clipped.reversed(),
            ] {
                assert!(matches!(
                    circle.chord_intersections(&carrier, &policy).unwrap(),
                    Classification::Decided(
                        BezierAlgebraicCuspSemicircleRetainedChordIntersections2::NoContacts
                    )
                ));
            }
        }
    }

    #[test]
    fn pair_radial_circle_retains_an_algebraic_rational_tangency() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let tangent = RationalBezier2::try_new(
            vec![
                Point2::new(Real::one(), -half.clone()),
                Point2::new(Real::one(), -half.clone()),
                Point2::new(Real::one(), half.clone()),
            ],
            vec![Real::one(), Real::one(), Real::one()],
        )
        .unwrap();
        let expected_parameter =
            algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()]);

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let circle = independent_pair_radial_unit_circle(&policy);

            // x=1, y=t^2-1/2 touches the unit circle at the simple selected
            // target parameter t=sqrt(1/2), but its circle incidence is the
            // even square (t^2-1/2)^2.
            let Classification::Decided((
                BezierAlgebraicCuspSemicircleRationalIntersections2::Contacts(contacts),
                Some(parameter_map),
            )) = circle
                .rational_intersections_with_parameter_map(&tangent, &policy)
                .unwrap()
            else {
                panic!("the pair-native algebraic tangency must complete");
            };
            let [contact] = contacts.as_slice() else {
                panic!("the tangent must have exactly one circle contact");
            };
            assert_eq!(
                contact
                    .other_parameter
                    .same_value(&expected_parameter, &policy)
                    .unwrap(),
                Classification::Decided(true),
            );
            assert_eq!(
                contact.location,
                BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            );
            assert_eq!(contact.tangent_cross_sign, RealSign::Zero);
            assert_eq!(
                contact.point.same_point(
                    &RationalBezierIntersectionPointEvidence2::Exact(Point2::from_values(1, 0)),
                    &policy,
                ),
                Classification::Decided(true),
            );
            let circle_parameter = parameter_map.contact_parameter(contact);
            let Classification::Decided(Some(mapped_point)) = circle_parameter
                .coincident_point_evidence(&circle, &policy)
                .unwrap()
            else {
                panic!("the pair-radial contact map must replay its point");
            };
            assert_eq!(
                mapped_point.same_point(&contact.point, &policy),
                Classification::Decided(true),
            );
        }
    }

    #[test]
    fn pair_radial_circle_retains_rational_circle_components() {
        // x=(1-u^2)/(1+u^2), y=2u/(1+u^2) traverses the first
        // quadrant of the unit circle. The pair-radial unit semicircle starts
        // at angle 225 degrees and traverses counterclockwise, so the retained
        // overlap ends at angle 45 degrees, u=sqrt(2)-1.
        let quarter_circle = RationalBezier2::from(
            RationalQuadraticBezier2::try_new(
                Point2::from_values(1, 0),
                Point2::from_values(1, 1),
                Point2::from_values(0, 1),
                Real::one(),
                Real::one(),
                Real::from(2_i8),
            )
            .unwrap(),
        );
        // v=4u(1-u) folds the same supporting quarter at u=1/2 and must
        // publish two regular cells with opposite parameter orientations.
        let eleven = Real::from(11_i8);
        let folded_quarter = RationalBezier2::try_new(
            vec![
                Point2::from_values(1, 0),
                Point2::from_values(1, 2),
                Point2::new(
                    (Real::from(-5_i8) / &eleven).unwrap(),
                    (Real::from(8_i8) / &eleven).unwrap(),
                ),
                Point2::from_values(1, 2),
                Point2::from_values(1, 0),
            ],
            vec![
                Real::one(),
                Real::one(),
                (&eleven / Real::from(3_i8)).unwrap(),
                Real::one(),
                Real::one(),
            ],
        )
        .unwrap();
        let overlap_end =
            algebraic_parameter(vec![Real::from(-1_i8), Real::from(2_i8), Real::one()]);
        let cusp_cut = (Real::from(3_i8) / Real::from(4_i8)).unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let circle = independent_pair_radial_unit_circle(&policy);
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::Overlaps(overlaps),
            ) = circle
                .rational_intersections(&quarter_circle, &policy)
                .unwrap()
            else {
                panic!("the pair-radial supporting-circle component must replay");
            };
            let [overlap] = overlaps.as_slice() else {
                panic!("the selected quarter must retain one monotone cell");
            };
            assert_eq!(
                overlap
                    .other_range()
                    .start()
                    .same_value(&BezierParameter2::Exact(Real::zero()), &policy)
                    .unwrap(),
                Classification::Decided(true),
            );
            assert_eq!(
                overlap
                    .other_range()
                    .end()
                    .same_value(&overlap_end, &policy)
                    .unwrap(),
                Classification::Decided(true),
            );
            assert_eq!(
                overlap.orientation(),
                RationalBezierOverlapOrientation2::Same,
            );
            assert_eq!(
                overlap
                    .cusp_end_parameter()
                    .order_to_real(&Real::one(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );

            let Classification::Decided(other_cut) = overlap
                .other_parameter_for_cusp(
                    &BezierAlgebraicCuspSemicircleParameter2::Exact(cusp_cut.clone()),
                    &policy,
                )
                .unwrap()
            else {
                panic!("an exact pair-radial cusp cut must invert on its rational component");
            };
            let Classification::Decided(round_trip) = overlap
                .cusp_parameter_for_other(&other_cut, &policy)
                .unwrap()
            else {
                panic!("the pair-radial rational cut must map back to the cusp domain");
            };
            assert_eq!(
                round_trip.order_to_real(&cusp_cut, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );

            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::Overlaps(reversed),
            ) = circle
                .rational_intersections(&quarter_circle.reversed(), &policy)
                .unwrap()
            else {
                panic!("rational reversal must retain the pair-radial component");
            };
            let [reversed] = reversed.as_slice() else {
                panic!("the reversed selected quarter must retain one monotone cell");
            };
            assert_eq!(
                reversed.orientation(),
                RationalBezierOverlapOrientation2::Reversed,
            );
            assert_eq!(
                reversed
                    .other_range()
                    .start()
                    .same_value(&overlap_end.unit_complement(), &policy)
                    .unwrap(),
                Classification::Decided(true),
            );

            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::Overlaps(folded),
            ) = circle
                .rational_intersections(&folded_quarter, &policy)
                .unwrap()
            else {
                panic!("a folded pair-radial component must retain regular cells");
            };
            assert_eq!(folded.len(), 2);
            assert_eq!(
                folded[0].orientation(),
                RationalBezierOverlapOrientation2::Same,
            );
            assert_eq!(
                folded[1].orientation(),
                RationalBezierOverlapOrientation2::Reversed,
            );
        }
    }

    #[test]
    fn separable_axis_content_exposes_rational_three_field_zero_exactly() {
        let parameters = nonlinear_rational_three_field_parameters();
        let mut coefficients = vec![vec![vec![Real::zero(); 2]; 2]; 2];
        coefficients[1][1][0] = Real::one();
        coefficients[1][0][1] = -Real::one();
        coefficients[0][1][1] = -Real::one();
        let primitive = TrivariatePolynomial2 { coefficients };
        let mut polynomial = primitive.clone();
        for axis in 0..3 {
            polynomial =
                trivariate_multiply_axis_linear(polynomial, axis, &Real::one(), &Real::one());
        }
        assert!(
            trivariate_reduce_selected_root_relations(
                &polynomial,
                &parameters[0],
                &parameters[1],
                &parameters[2],
            )
            .is_none()
        );
        assert!(
            trivariate_binary_related_parameter_sign(
                &polynomial,
                &parameters[0],
                &parameters[1],
                &parameters[2],
            )
            .unwrap()
            .is_none()
        );
        let (reduced, factor_sign) = trivariate_strip_axis_contents(
            &polynomial,
            &parameters[0],
            &parameters[1],
            &parameters[2],
        )
        .unwrap()
        .expect("all three nonzero separable factors must be removed");
        assert_eq!(reduced.coefficients, primitive.coefficients);
        assert_eq!(factor_sign, Some(RealSign::Positive));
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                trivariate_parameter_triple_sign_by_refinement(
                    &polynomial,
                    &parameters[0],
                    &parameters[1],
                    &parameters[2],
                    attempt,
                )
                .unwrap()
            });
            assert_eq!(outcome.value, Classification::Decided(RealSign::Zero));
            assert_eq!(outcome.certainty, crate::CurveCertainty::Certified);
        }
    }

