    #[test]
    fn translated_distinct_field_chord_zero_is_exact_in_strict() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        // alpha=sqrt(1/2), beta=1-alpha, gamma=alpha-1/2.
        // The independently represented points (alpha,0), (0,beta), and
        // (gamma,gamma) are collinear because alpha*beta=gamma and
        // alpha+beta=1. The full chord identity appears only after replaying
        // the certified pairwise affine root relations.
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                independent_field_collinear_chord_side(
                    [
                        vec![-half.clone(), Real::zero(), Real::one()],
                        vec![half.clone(), Real::from(-2_i8), Real::one()],
                        vec![-quarter.clone(), Real::one(), Real::one()],
                    ],
                    attempt,
                )
            });
            assert_eq!(
                outcome.value,
                Classification::Decided(crate::classify::LineSide::On),
            );
            assert_eq!(outcome.certainty, crate::CurveCertainty::Certified);
        }
    }

    #[test]
    fn scaled_distinct_field_chord_zero_is_exact_in_strict() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let eighth = (Real::one() / Real::from(8_i8)).unwrap();
        let eighteenth = (Real::one() / Real::from(18_i8)).unwrap();
        // alpha=sqrt(1/2), beta=alpha/2, gamma=alpha/3. The same three
        // coordinate forms are collinear because alpha*beta =
        // gamma*(alpha+beta). The independently represented fields expose
        // only exact rational scaling relations.
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                independent_field_collinear_chord_side(
                    [
                        vec![-half.clone(), Real::zero(), Real::one()],
                        vec![-eighth.clone(), Real::zero(), Real::one()],
                        vec![-eighteenth.clone(), Real::zero(), Real::one()],
                    ],
                    attempt,
                )
            });
            assert_eq!(
                outcome.value,
                Classification::Decided(crate::classify::LineSide::On),
            );
            assert_eq!(outcome.certainty, crate::CurveCertainty::Certified);
        }
    }

    #[test]
    fn nonaffine_distinct_field_chord_zero_is_exact_in_strict() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let third = (Real::one() / Real::from(3_i8)).unwrap();
        // alpha=sqrt(1/2), beta=sqrt(1/3), and
        // gamma=alpha*beta/(alpha+beta). Gamma is the unique unit root of
        // x^4-10*x^2+1. The three coordinate forms remain exactly collinear,
        // while no pair is related by a rational affine transform.
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let outcome = crate::policy::resolve_certified_value(&policy, |attempt| {
                independent_field_collinear_chord_side(
                    [
                        vec![-half.clone(), Real::zero(), Real::one()],
                        vec![-third.clone(), Real::zero(), Real::one()],
                        vec![
                            Real::one(),
                            Real::zero(),
                            Real::from(-10_i8),
                            Real::zero(),
                            Real::one(),
                        ],
                    ],
                    attempt,
                )
            });
            assert_eq!(
                outcome.value,
                Classification::Decided(crate::classify::LineSide::On),
            );
            assert_eq!(outcome.certainty, crate::CurveCertainty::Certified);
        }
    }

    #[test]
    fn nested_independent_cusp_disks_complete_all_region_booleans() {
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let center_numerator = vec![Real::zero(), Real::one()];
            let first = synthetic_selected_cusp_semicircle(
                center_numerator.clone(),
                vec![Real::zero()],
                (Real::one() / Real::from(3_i8)).unwrap(),
                (Real::one() / Real::from(2_i8)).unwrap(),
                (Real::from(2_i8) / Real::from(3_i8)).unwrap(),
                Real::one(),
                false,
                &policy,
            );
            let second = synthetic_selected_cusp_semicircle(
                center_numerator,
                vec![Real::zero()],
                (Real::one() / Real::from(2_i8)).unwrap(),
                (Real::from(2_i8) / Real::from(3_i8)).unwrap(),
                (Real::from(3_i8) / Real::from(4_i8)).unwrap(),
                Real::from(3_i8),
                false,
                &policy,
            );
            let disk = |upper: BezierAlgebraicCuspSemicircle2| {
                let lower = upper.complementary_half();
                let boundary = crate::CurveRegionBoundaryLoop2::new(
                    vec![
                        crate::BezierSplitFragment2::AlgebraicCuspSemicircle(
                            BezierAlgebraicCuspSemicircleFragment2::full(upper, &policy),
                        ),
                        crate::BezierSplitFragment2::AlgebraicCuspSemicircle(
                            BezierAlgebraicCuspSemicircleFragment2::full(lower, &policy),
                        ),
                    ],
                    &policy,
                )
                .unwrap();
                crate::CurveRegion2::try_new_with_loop_topology(
                    vec![boundary],
                    vec![crate::CurveRegionLoopRole::Material],
                    vec![crate::FillRule::NonZero],
                    vec![crate::CurveBoundaryInteriorSide2::Left],
                )
                .unwrap()
            };
            let inner = disk(first);
            let outer = disk(second);
            let booleans = inner
                .boolean_regions(&outer, &policy)
                .expect("independent selected-field disks must complete one Boolean topology")
                .into_value();
            assert_eq!(booleans.topology_point_classification_count(), 2);
            assert!(booleans.union().has_algebraic_fragments());
            assert!(booleans.intersection().has_algebraic_fragments());
            assert!(booleans.difference().is_empty());
            assert!(booleans.xor().has_algebraic_fragments());
        }
    }

    #[test]
    fn algebraic_cusp_circle_degenerate_projection_is_filtered_at_the_selected_root() {
        // This rational reparameterization has homogeneous Bernstein controls
        // X=[1,1,0], Y=[0,1,2], W=[1,1,2], hence
        // x=(1-u^2)/(1+u^2), y=2u/(1+u^2) with rational coefficients.
        let quarter_circle = RationalBezier2::from(
            RationalQuadraticBezier2::try_new(
                Point2::new(Real::one(), Real::zero()),
                Point2::new(Real::one(), Real::one()),
                Point2::new(Real::zero(), Real::one()),
                Real::one(),
                Real::one(),
                Real::from(2_i8),
            )
            .unwrap(),
        );
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let foreign_component =
                synthetic_reducible_cusp_semicircle((1, 4), ((1, 5), (1, 3)), &policy);
            assert_eq!(
                foreign_component
                    .rational_intersections(&quarter_circle, &policy)
                    .unwrap(),
                Classification::Decided(
                    BezierAlgebraicCuspSemicircleRationalIntersections2::Contacts(Vec::new())
                )
            );

            let selected_component =
                synthetic_reducible_cusp_semicircle((3, 4), ((2, 3), (4, 5)), &policy);
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::Overlaps(overlaps),
            ) = selected_component
                .rational_intersections(&quarter_circle, &policy)
                .unwrap()
            else {
                panic!("the selected rational circle component must publish overlap evidence");
            };
            let [overlap] = overlaps.as_slice() else {
                panic!("the selected quarter circle must produce one monotone overlap");
            };
            assert_eq!(
                overlap.other_range(),
                &BezierParameterRange2::new_validated(
                    BezierParameter2::Exact(Real::zero()),
                    BezierParameter2::Exact(Real::one()),
                ),
            );
            assert_eq!(
                overlap.orientation(),
                RationalBezierOverlapOrientation2::Same
            );
            assert_eq!(
                overlap
                    .cusp_start_parameter()
                    .order_to_real(&Real::zero(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                overlap
                    .cusp_end_parameter()
                    .order_to_real(&(Real::one() / Real::from(2_i8)).unwrap(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );

            let quarter = (Real::one() / Real::from(4_i8)).unwrap();
            let one_third = (Real::one() / Real::from(3_i8)).unwrap();
            let cusp_cut = BezierAlgebraicCuspSemicircleParameter2::Exact(quarter.clone());
            let Classification::Decided(rational_cut) = overlap
                .other_parameter_for_cusp(&cusp_cut, &policy)
                .unwrap()
            else {
                panic!("an exact cusp cut must invert onto the rational circle component");
            };
            assert_eq!(
                rational_cut
                    .same_value(&BezierParameter2::Exact(one_third.clone()), &policy)
                    .unwrap(),
                Classification::Decided(true),
            );
            let Classification::Decided(round_trip) = overlap
                .cusp_parameter_for_other(&rational_cut, &policy)
                .unwrap()
            else {
                panic!("the rational component cut must map back to the cusp domain");
            };
            assert_eq!(
                round_trip.order_to_real(&quarter, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );

            let reversed = quarter_circle.reversed();
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::Overlaps(reversed_overlaps),
            ) = selected_component
                .rational_intersections(&reversed, &policy)
                .unwrap()
            else {
                panic!("rational source reversal must preserve the selected component");
            };
            let [reversed_overlap] = reversed_overlaps.as_slice() else {
                panic!("the reversed quarter circle must remain one overlap");
            };
            assert_eq!(
                reversed_overlap.orientation(),
                RationalBezierOverlapOrientation2::Reversed,
            );
            let Classification::Decided(reversed_cut) = reversed_overlap
                .other_parameter_for_cusp(&cusp_cut, &policy)
                .unwrap()
            else {
                panic!("the exact cusp cut must invert through rational reversal");
            };
            assert_eq!(
                reversed_cut
                    .same_value(&BezierParameter2::Exact(Real::one() - &one_third), &policy,)
                    .unwrap(),
                Classification::Decided(true),
            );

            // v=4u(1-u) composes the same quarter-circle parameterization with
            // one exact stationary reversal at u=1/2. The component authority
            // must publish both regular monotone cells instead of inferring a
            // zero range from the equal endpoints.
            let three = Real::from(3_i8);
            let eleven = Real::from(11_i8);
            let folded_quarter = RationalBezier2::try_new(
                vec![
                    Point2::from_values(1, 0),
                    Point2::from_values(1, 2),
                    Point2::new(
                        (Real::from(-5_i8) / &eleven).unwrap(),
                        (Real::from(8_i8) / &eleven).unwrap(),
                    ),
                    Point2::from_values(1, 2),
                    Point2::from_values(1, 0),
                ],
                vec![
                    Real::one(),
                    Real::one(),
                    (&eleven / &three).unwrap(),
                    Real::one(),
                    Real::one(),
                ],
            )
            .unwrap();
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::Overlaps(folded_overlaps),
            ) = selected_component
                .rational_intersections(&folded_quarter, &policy)
                .unwrap()
            else {
                panic!("the stationary rational circle must split into regular overlaps");
            };
            assert_eq!(folded_overlaps.len(), 2);
            assert_eq!(
                folded_overlaps[0].orientation(),
                RationalBezierOverlapOrientation2::Same,
            );
            assert_eq!(
                folded_overlaps[1].orientation(),
                RationalBezierOverlapOrientation2::Reversed,
            );
            let half = (Real::one() / Real::from(2_i8)).unwrap();
            for (overlap, expected_start, expected_end) in [
                (&folded_overlaps[0], Real::zero(), half.clone()),
                (&folded_overlaps[1], half.clone(), Real::one()),
            ] {
                assert_eq!(
                    overlap.other_range(),
                    &BezierParameterRange2::new_validated(
                        BezierParameter2::Exact(expected_start),
                        BezierParameter2::Exact(expected_end),
                    ),
                );
                assert_eq!(
                    overlap
                        .cusp_start_parameter()
                        .order_to_real(&Real::zero(), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
                assert_eq!(
                    overlap
                        .cusp_end_parameter()
                        .order_to_real(&half, &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
            }

            let lower_quarter = RationalBezier2::from(
                RationalQuadraticBezier2::try_new(
                    Point2::new(Real::one(), Real::zero()),
                    Point2::new(Real::one(), Real::from(-1_i8)),
                    Point2::new(Real::zero(), Real::from(-1_i8)),
                    Real::one(),
                    Real::one(),
                    Real::from(2_i8),
                )
                .unwrap(),
            );
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::Contacts(lower_contacts),
            ) = selected_component
                .rational_intersections(&lower_quarter, &policy)
                .unwrap()
            else {
                panic!("an opposite-half circle must retain only its selected endpoint");
            };
            let [lower_contact] = lower_contacts.as_slice() else {
                panic!("the opposite quarter circle must touch one selected endpoint");
            };
            assert_eq!(
                lower_contact.location,
                BezierAlgebraicCuspSemicircleContactLocation2::Start,
            );
            assert_eq!(lower_contact.tangent_cross_sign, RealSign::Zero);
        }
    }

    #[test]
    fn exact_parallel_is_one_word_and_distances_share_lazy_source_kernel() {
        let source = QuadraticBezier2::new(
            Point2::new(Real::zero(), Real::zero()),
            Point2::new(Real::one(), Real::one()),
            Point2::new(Real::from(2_i8), Real::zero()),
        );
        let parallel = source.parallel_left(Real::one()).unwrap();
        let clone = parallel.clone();
        let redistanced = parallel.with_distance(Real::from(2_i8));

        assert_eq!(
            std::mem::size_of::<BezierParallel2>(),
            std::mem::size_of::<usize>()
        );
        assert!(Arc::ptr_eq(&parallel.data, &clone.data));
        assert!(!Arc::ptr_eq(&parallel.data, &redistanced.data));
        assert!(Arc::ptr_eq(&parallel.data.source, &redistanced.data.source));
        assert!(parallel.data.source.differential.get().is_none());
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        assert!(matches!(
            clone.point_at(&half, &CurveContext::STRICT).unwrap(),
            Classification::Decided(_)
        ));
        assert!(parallel.data.source.differential.get().is_some());
        assert!(redistanced.data.source.differential.get().is_some());
        assert!(redistanced.data.certified_ph_offset.get().is_none());
    }

    #[test]
    fn certified_circle_tangent_remains_nontransverse_after_residual_deflation() {
        let source = QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(
                Point2::new(Real::zero(), Real::zero()),
                Point2::new(Real::one(), Real::zero()),
            )
            .unwrap(),
        );
        let parallel = source.parallel_left(Real::one()).unwrap();
        let zero = Real::zero();
        let incidence = parallel
            .circle_incidence(
                &Point2::new(Real::zero(), Real::zero()),
                &Real::one(),
                &[(zero.clone(), 3)],
                &CurveContext::STRICT,
            )
            .unwrap();
        let Classification::Decided(contacts) = incidence else {
            panic!("the certified line/circle tangent must be decided");
        };
        let [(parameter, radial_crossing_sign)] = contacts.as_slice() else {
            panic!("the tangent circle must have one retained contact");
        };
        assert_eq!(parameter.as_exact(), Some(&zero));
        assert!(radial_crossing_sign.is_none());
    }

