    #[test]
    fn incident_parabola_parallel_line_retains_the_regular_exterior_contact() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let radius = (Real::from(13_i8) / Real::from(5_i8)).unwrap();
        let height = (Real::from(61_i8) / Real::from(25_i8)).unwrap();
        let expected = (Real::from(6_i8) / Real::from(5_i8)).unwrap();
        let parallel = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half, Real::zero()),
            Point2::from_values(1, 1),
        )
        .parallel_left(radius)
        .unwrap();
        let line = LineSeg2::try_new(
            Point2::new(Real::from(-4_i8), height.clone()),
            Point2::new(Real::from(4_i8), height),
        )
        .unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(BezierParallelIncidence2::Parameters(parameters)) =
                parallel
                    .supporting_line_incidence_on_incident_ray_with_direction(
                        &line,
                        &Real::one(),
                        &Real::zero(),
                        &Real::one(),
                        BezierParameterRayDirection2::Increasing,
                        &policy,
                    )
                    .unwrap()
            else {
                panic!("the regular polynomial incident cell must be decided");
            };
            let [parameter] = parameters.as_slice() else {
                panic!("the increasing incident cell has one selected-branch contact");
            };
            assert_eq!(parameter.as_exact(), Some(&expected));

            let half = (Real::one() / Real::from(2_i8)).unwrap();
            let direction_x = (Real::from(5_i8) / Real::from(13_i8)).unwrap();
            let direction_y = (Real::from(12_i8) / Real::from(13_i8)).unwrap();
            let algebraic_parallel = QuadraticBezier2::new(
                Point2::from_values(0, 0),
                Point2::new(half.clone(), Real::zero()),
                Point2::from_values(1, 1),
            )
            .parallel_left(half.clone())
            .unwrap();
            let line_start = Point2::new(
                Real::one() - (Real::from(6_i8) / Real::from(13_i8)).unwrap(),
                Real::one() + (Real::from(5_i8) / Real::from(26_i8)).unwrap(),
            );
            let line = LineSeg2::try_new(
                line_start.clone(),
                line_start.translated(
                    Real::from(2_i8) * &direction_x,
                    Real::from(2_i8) * &direction_y,
                ),
            )
            .unwrap();
            let Classification::Decided(BezierParallelIncidence2::Parameters(parameters)) =
                algebraic_parallel
                    .supporting_line_incidence_on_incident_ray_with_direction(
                        &line,
                        &direction_x,
                        &direction_y,
                        &Real::one(),
                        BezierParameterRayDirection2::Increasing,
                        &policy,
                    )
                    .unwrap()
            else {
                panic!("the algebraic regular incident cell must be decided");
            };
            let [parameter] = parameters.as_slice() else {
                panic!("the algebraic incident cell must have one contact: {parameters:?}");
            };
            assert!(matches!(parameter, BezierParameter2::Algebraic(_)));
            let Classification::Decided((_, Some(line_parameter))) = algebraic_parallel
                .supporting_line_contact_evidence_affine(&line, parameter, &policy)
                .unwrap()
            else {
                panic!("the algebraic contact must have an affine line parameter");
            };
            assert!(matches!(line_parameter, BezierParameter2::Algebraic(_)));
            assert_eq!(
                line_parameter
                    .cmp_by_refinement(&BezierParameter2::Exact(Real::zero()), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Greater),
            );
            assert_eq!(
                line_parameter
                    .cmp_by_refinement(&BezierParameter2::Exact(Real::one()), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Less),
            );
        }
    }

    #[test]
    fn incident_parabola_parallel_circle_retains_exact_and_algebraic_contacts() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let expected = (Real::from(6_i8) / Real::from(5_i8)).unwrap();
        let parallel = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half.clone(), Real::zero()),
            Point2::from_values(1, 1),
        )
        .parallel_left(half)
        .unwrap();
        let center = Point2::new(
            Real::one(),
            (Real::from(3923_i64) / Real::from(2150_i64)).unwrap(),
        );
        let radius = (Real::from(349_i64) / Real::from(1075_i64)).unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(contacts) = parallel
                .circle_incidence_on_incident_ray(
                    &center,
                    &(&radius * &radius),
                    &Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the regular polynomial incident cell must be decided");
            };
            let [(first, None), (second, None)] = contacts.as_slice() else {
                panic!("the incident cell must retain both selected circle contacts: {contacts:?}");
            };
            assert_eq!(first.as_exact(), Some(&expected));
            assert!(matches!(second, BezierParameter2::Algebraic(_)));
            assert_eq!(
                second.cmp_by_refinement(first, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Greater),
            );
        }
    }

    #[test]
    fn represented_derivative_scale_fast_path_matches_polynomial_certificate() {
        let point = |x, y| Point2::new(Real::from(x), Real::from(y));
        let sources = [
            BezierParallelSource2::Quadratic(QuadraticBezier2::new(
                point(0, 0),
                point(1, 2),
                point(3, 0),
            )),
            BezierParallelSource2::Cubic(CubicBezier2::new(
                point(0, 0),
                point(1, 3),
                point(3, -2),
                point(5, 1),
            )),
            BezierParallelSource2::Rational(
                RationalBezier2::try_new(
                    vec![point(0, 0), point(1, 2), point(3, -1), point(4, 1)],
                    vec![Real::one(), Real::from(2_i8), Real::from(3_i8), Real::one()],
                )
                .unwrap(),
            ),
        ];
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let radical = Real::from(2_i8).sqrt().unwrap();
        let distances = [-radical.clone(), -half.clone(), Real::zero(), half, radical];

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            for source in &sources {
                for distance in &distances {
                    let parallel = BezierParallel2::from_source(source.clone(), distance.clone());
                    for numerator in 0..=4_u8 {
                        let parameter = (Real::from(numerator) / Real::from(4_u8)).unwrap();
                        let retained = BezierParameter2::Exact(parameter.clone());
                        assert_eq!(
                            parallel.parallel_derivative_scale_sign_at_exact(&parameter, &policy),
                            parallel.parallel_derivative_scale_sign_from_polynomials(
                                &retained, &policy,
                            ),
                            "source={source:?}, distance={distance:?}, parameter={parameter:?}, policy={policy:?}",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn general_algebraic_cusp_points_are_exact_rational_images() {
        let point = |x, y| Point2::new(Real::from(x), Real::from(y));
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let three_quarters = &half + &quarter;
        let parallel = CubicBezier2::new(point(0, 0), point(0, 4), point(4, -4), point(4, 0))
            .parallel_left(half.clone())
            .unwrap();
        let Classification::Decided(analysis) = parallel
            .singularity_analysis(&CurveContext::STRICT)
            .unwrap()
        else {
            panic!("general cubic cusp analysis must be decided");
        };
        let BezierParameter2::Algebraic(cusp) = &analysis.parallel_cusps()[0] else {
            panic!("the general cubic cusp must remain algebraic");
        };
        let retained_parameter = BezierParameter2::Algebraic(cusp.clone());
        let source = parallel.source_power_basis().unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let source_point = RationalBezierAlgebraicPointImage2::from_retained_expression(
                cusp.clone(),
                parameter_representation(cusp, &policy),
                source.x_numerator.to_vec(),
                source.y_numerator.to_vec(),
                source
                    .weight
                    .map_or_else(|| vec![Real::one()], ToOwned::to_owned),
                "retained the exact source point for cusp construction verification",
            );
            let construct = |distance: &Real| {
                let Classification::Decided(Some(image)) = parallel
                    .algebraic_parallel_cusp_point_image(cusp, distance, &policy)
                    .unwrap()
                else {
                    panic!("selected cusp point image must be decided");
                };
                assert!(matches!(
                    image.status(),
                    BezierAlgebraicImageStatus::Transformed
                        | BezierAlgebraicImageStatus::RetainedRationalExpression
                ));
                image
            };
            let inner = construct(&quarter);
            let center = construct(&half);
            let outer = construct(&three_quarters);

            assert_rational_image_distance(
                &center,
                &source_point,
                &half,
                &retained_parameter,
                &policy,
            );
            assert_rational_image_distance(&outer, &inner, &half, &retained_parameter, &policy);
            assert_rational_image_midpoint(&inner, &outer, &center, &retained_parameter, &policy);

            let differential = parallel.differential().unwrap();
            let center_coordinates = rational_image_coordinates(&center);
            let source_coordinates = rational_image_coordinates(&source_point);
            let (dx_numerator, dx_denominator) =
                rational_coordinate_difference(center_coordinates[0], source_coordinates[0]);
            let (dy_numerator, dy_denominator) =
                rational_coordinate_difference(center_coordinates[1], source_coordinates[1]);
            let tangent_dot_displacement = polynomial_add(
                &polynomial_multiply(
                    &polynomial_multiply(&dx_numerator, &differential.tangent_x),
                    &dy_denominator,
                ),
                &polynomial_multiply(
                    &polynomial_multiply(&dy_numerator, &differential.tangent_y),
                    &dx_denominator,
                ),
            );
            assert_algebraic_polynomial_sign(
                tangent_dot_displacement,
                &retained_parameter,
                RealSign::Zero,
                &policy,
            );
            let tangent_cross_displacement = polynomial_subtract(
                &polynomial_multiply(
                    &polynomial_multiply(&dy_numerator, &differential.tangent_x),
                    &dx_denominator,
                ),
                &polynomial_multiply(
                    &polynomial_multiply(&dx_numerator, &differential.tangent_y),
                    &dy_denominator,
                ),
            );
            assert_algebraic_polynomial_sign(
                tangent_cross_displacement,
                &retained_parameter,
                RealSign::Positive,
                &policy,
            );
        }

        let BezierParameter2::Algebraic(non_cusp) =
            algebraic_parameter(vec![Real::from(-1_i8), Real::from(2_i8), Real::one()])
        else {
            panic!("the irrational non-cusp parameter must remain algebraic");
        };
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            assert!(matches!(
                parallel
                    .algebraic_parallel_cusp_point_image(&non_cusp, &half, &policy)
                    .unwrap(),
                Classification::Decided(None)
            ));
        }
    }

    #[test]
    fn analytic_parallel_self_intersection_removes_the_parameter_diagonal() {
        let point = |x, y| Point2::new(Real::from(x), Real::from(y));
        let source = CubicBezier2::new(point(0, 0), point(1, 4), point(3, -4), point(4, 0));
        let distance = (Real::one() / Real::from(2_u8)).unwrap();
        let parallel = source.parallel_left(distance).unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let result = match parallel.self_intersections(&policy).unwrap() {
                Classification::Decided(result) => result,
                Classification::Uncertain(reason) => {
                    panic!("self-intersection replay: {reason:?}")
                }
            };
            assert!(result.is_complete());
            let [contact] = result.contacts() else {
                panic!("expected one unordered off-diagonal contact");
            };
            assert_eq!(
                contact
                    .first_parameter()
                    .cmp_by_refinement(contact.second_parameter(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Less)
            );
            assert!(matches!(
                contact.tangent_cross_sign(),
                Some(RealSign::Positive | RealSign::Negative)
            ));
        }
    }

